      "path": "internal/router/routes_knowledge.go",
      "content": "package router\n\nimport (\n\t\"net/http\"\n\n\t\"github.com/gin-gonic/gin\"\n\n\t\"github.com/Tencent/WeKnora/internal/handler\"\n)\n\n// RegisterChunkerDebugRoutes wires the read-only chunker preview endpoint\n// used by the KB editor's debug panel. Stateless — uses no service deps.\n//\n// Viewer+ floor: the endpoint surfaces inside the tenant UI, so any\n// authenticated tenant member can call it; revoked accounts whose JWT\n// has not yet expired are kept out by the role check, matching the\n// rest of the RBAC matrix in this file.\nfunc RegisterChunkerDebugRoutes(r *gin.RouterGroup, g *rbacGuards) {\n\tg.apiKeyRoute(r, http.MethodPost, \"/chunker/preview\", apiKeyRetrieve(apiKeyIngest(apiKeyFullAccess())), g.Viewer(), handler.PreviewChunking)\n}\n\n// RegisterChunkRoutes 注册分块相关的路由\n//\n// Mutating routes addressed via :knowledge_id inherit per-KB ownership\n// from the owning knowledge entry's KB (PR 5, #1303); the chain hop is\n// shared with RegisterKnowledgeRoutes via OwnedChunkKBOrAdmin so the\n// same \"creator-of-the-KB OR Admin+\" rule applies to chunk edits.\nfunc RegisterChunkRoutes(r *gin.RouterGroup, handler *handler.ChunkHandler, g *rbacGuards) {\n\t// 分块路由组。Scoped API key 需要 ingest 能力写内容，retrieve 能力读内容；\n\t// 两者仍受 KB 白名单约束。\n\tchunks := g.apiKeyGroup(r.Group(\"/chunks\"), apiKeyIngest(apiKeyFullAccess()))\n\tchunkRead := chunks.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\t// 获取分块列表 — Viewer+ 且对父 KB 有 read 权限（own / shared / via shared agent）\n\t\tchunkRead.GET(\"/:knowledge_id\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"knowledge_id\"), handler.ListKnowledgeChunks)\n\t\t// 通过chunk_id获取单个chunk（不需要knowledge_id） — Viewer+ 且对父 KB 有 read 权限\n\t\tchunkRead.GET(\"/by-id/:id\", g.Viewer(), g.KBAccessReadFromChunkIDParam(\"id\"), handler.GetChunkByIDOnly)\n\t\tchunkRead.GET(\"/:knowledge_id/:id/revisions\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"knowledge_id\"), handler.ListChunkRevisions)\n\t\t// 删除分块 — KB owner OR Admin+，且对父 KB 有 write 权限\n\t\tchunks.DELETE(\"/:knowledge_id/:id\", g.OwnedChunkKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"knowledge_id\"), handler.DeleteChunk)\n\t\t// 删除知识下的所有分块 — KB owner OR Admin+，且对父 KB 有 write 权限\n\t\tchunks.DELETE(\"/:knowledge_id\", g.OwnedChunkKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"knowledge_id\"), handler.DeleteChunksByKnowledgeID)\n\t\t// 更新分块信息 — KB owner OR Admin+，且对父 KB 有 write 权限\n\t\tchunks.PUT(\"/:knowledge_id/:id\", g.OwnedChunkKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"knowledge_id\"), handler.UpdateChunk)\n\t\tchunks.POST(\"/:knowledge_id/:id/revert\", g.OwnedChunkKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"knowledge_id\"), handler.RevertChunk)\n\t\t// 删除单个生成的问题（通过分块 id） — 与其它 chunk mutation 一致：\n\t\t// KB owner OR Admin+。早期这里因为链路 (chunk_id -> knowledge_id ->\n\t\t// kb -> creator_id) 还没接通，被临时降级成 Contributor，导致一个\n\t\t// 「能编辑所有 chunk 的同样规则在这条路由上反而更宽松」的不一致。\n\t\t// 现在通过 KBCreatorLookupFromChunkIDParam 把那一跳补上，统一矩阵。\n\t\tchunks.DELETE(\"/by-id/:id/questions\", g.OwnedChunkKBOrAdminFromChunkID(), g.KBAccessWriteFromChunkIDParam(\"id\"), handler.DeleteGeneratedQuestion)\n\t\tchunks.PUT(\"/by-id/:id/questions\", g.OwnedChunkKBOrAdminFromChunkID(), g.KBAccessWriteFromChunkIDParam(\"id\"), handler.UpsertGeneratedQuestion)\n\t\tchunks.POST(\"/by-id/:id/questions/regenerate\", g.OwnedChunkKBOrAdminFromChunkID(), g.KBAccessWriteFromChunkIDParam(\"id\"), handler.RegenerateGeneratedQuestions)\n\t}\n}\n\n// RegisterKnowledgeRoutes 注册知识相关的路由\n//\n// Per-KB ownership applies on the per-:id mutating routes (PR 5,\n// #1303): the URL :id is a knowledge id, OwnedKnowledgeKBOrAdmin\n// walks it back to KB.CreatorID so a Contributor who owns the KB can\n// edit/delete any of its documents while a non-owner Contributor gets\n// 403. KB-scoped upload routes (`/knowledge-bases/:id/knowledge/...`)\n// reuse OwnedKBOrAdmin because the URL :id is the KB id directly.\n// Body-scoped batch operations have a Contributor route gate and resolve\n// their KB ownership plus Editor operation grant inside the handler.\nfunc RegisterKnowledgeRoutes(r *gin.RouterGroup, handler *handler.KnowledgeHandler, g *rbacGuards) {\n\t// 知识库下的知识路由组（URL :id is the KB id）。Scoped API key 需要\n\t// ingest 能力才能写内容，且仍受 KB 范围限制；清空 KB 只允许 full-access key。\n\tkb := g.apiKeyGroup(r.Group(\"/knowledge-bases/:id/knowledge\"), apiKeyIngest(apiKeyFullAccess()))\n\tkbRead := kb.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\tkb.POST(\"/file\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.CreateKnowledgeFromFile)\n\t\tkb.POST(\"/url\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.CreateKnowledgeFromURL)\n\t\tkb.POST(\"/manual\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.CreateManualKnowledge)\n\t\tkbRead.GET(\"\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListKnowledge)\n\t\t// 原始文件下载沿用单文件下载的 Contributor + Editor 权限边界。\n\t\tkbRead.POST(\"/batch-download\", g.Contributor(), g.KBAccessWrite(\"id\"), handler.BatchDownloadKnowledge)\n\t\tkbRead.GET(\"/folders\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListKnowledgeFolders)\n\t\tkb.PUT(\"/folders\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.RenameKnowledgeFolder)\n\t\t// Clearing all contents under a KB is a destructive op; gate\n\t\t// behind Admin instead of Contributor.\n\t\tkb.With(apiKeyFullAccess()).DELETE(\"\", g.Admin(), g.KBAccessWrite(\"id\"), handler.ClearKnowledgeBaseContents)\n\t}\n\n\t// Image gallery: list every image asset of a KB (read-only, Viewer+).\n\t// Lives directly under /knowledge-bases/:id so it parallels /knowledge,\n\t// /faq and /tags rather than nesting under /knowledge (documents).\n\tkbImages := g.apiKeyGroup(r.Group(\"/knowledge-bases/:id\"), apiKeyRetrieve(apiKeyFullAccess()))\n\tkbImagesRead := kbImages.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\tkbImagesRead.GET(\"/images\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListImages)\n\t\t// Same listing with the filter as a JSON body: knowledge_ids escapes\n\t\t// the URL-length cap, so the source picker's select-all can name\n\t\t// every document of a large KB.\n\t\tkbImagesRead.POST(\"/images\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListImagesPost)\n\t\t// Self-describing gallery contract: live attribute sources, the\n\t\t// resolved attribute list (definitions + merged usage) and the\n\t\t// caller's search activation state. Per-KB because KB-defined\n\t\t// attribute sources resolve against :id.\n\t\tkbImagesRead.GET(\"/gallery-config\", g.Viewer(), g.KBAccessRead(\"id\"), handler.GetGalleryConfig)\n\t}\n\n\t// Whole-KB index rebuild after an indexing-strategy change (called by the\n\t// KB settings modal via POST /api/v1/knowledge-bases/:id/rebuild-index).\n\t// Content write like /knowledge/batch-reparse: ingest-capable API keys\n\t// may call it; JWT callers need Contributor+ with KB write access, and\n\t// the handler re-validates ownership before enqueueing.\n\tkbRebuild := g.apiKeyGroup(r.Group(\"/knowledge-bases/:id\"), apiKeyIngest(apiKeyFullAccess()))\n\tkbRebuild.POST(\"/rebuild-index\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.RebuildKnowledgeBaseIndex)\n\n\t// 知识路由组（URL :id is a knowledge id; the guard walks it to the parent KB）\n\tkgrp := r.Group(\"/knowledge\")\n\tk := g.apiKeyGroup(kgrp, apiKeyIngest(apiKeyFullAccess()))\n\tkRead := k.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\t// Cross-knowledge endpoints (no :id) can't be gated on a single\n\t\t// KB via the URL — they accept a kb_id (or source/target KB) in the\n\t\t// body and the handler fans out the access check itself. /batch and\n\t\t// /search are read routes (retrieve). /move, /batch-delete,\n\t\t// /batch-reparse and /tags are content writes that each bound\n\t\t// themselves to a single (or source+target) KB and enforce the API\n\t\t// key's KB allow-list downstream — MoveKnowledge via\n\t\t// requireTenantAPIKeyKnowledgeBases(source,target); the batch ops via\n\t\t// validateKnowledgeBaseAccessWithKBID (requireTenantAPIKeyKnowledgeBase)\n\t\t// plus a per-item \"belongs to the authorized KB\" check in the handler\n\t\t// and service. They are therefore declared for API keys under the\n\t\t// ingest capability, matching their single-document siblings\n\t\t// (k.DELETE(\"/:id\"), k.POST(\"/:id/reparse\"), k.PUT(\"/:id\")).\n\t\tkRead.GET(\"/batch\", g.Viewer(), handler.GetKnowledgeBatch)\n\t\tkRead.GET(\"/:id\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"id\"), handler.GetKnowledge)\n\t\tkRead.GET(\"/:id/stages\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"id\"), handler.GetKnowledgeSpans)\n\t\tkRead.GET(\"/:id/spans\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"id\"), handler.GetKnowledgeSpans)\n\t\tk.DELETE(\"/:id\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.DeleteKnowledge)\n\t\tk.PUT(\"/:id\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.UpdateKnowledge)\n\t\tk.POST(\"/:id/regenerate-summary\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.RegenerateKnowledgeSummary)\n\t\tk.PUT(\"/manual/:id\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.UpdateManualKnowledge)\n\t\tk.POST(\"/:id/reparse\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.ReparseKnowledge)\n\t\tk.POST(\"/:id/cancel-parse\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.CancelKnowledgeParse)\n\t\t// Downloading exposes the original source file, so it has a stricter\n\t\t// boundary than viewing parsed content or previewing it: tenant Viewers\n\t\t// cannot download from their own workspace, and org-shared Viewer access\n\t\t// cannot download from the source workspace. API keys still follow the\n\t\t// retrieve capability declared by kRead; role guards intentionally defer\n\t\t// machine-principal authorization to the API-key gate.\n\t\tkRead.GET(\"/:id/download\", g.Contributor(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.DownloadKnowledgeFile)\n\t\tkRead.GET(\"/:id/preview\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"id\"), handler.PreviewKnowledgeFile)\n\t\tk.PUT(\"/image/:id/:chunk_id\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.UpdateImageInfo)\n\t\tkRead.GET(\"/search\", g.Viewer(), handler.SearchKnowledge)\n\t\tkRead.GET(\"/move/progress/:task_id\", g.Viewer(), handler.GetKnowledgeMoveProgress)\n\t\t// Batch / cross-KB content writes: JWT Contributor+, or an API key\n\t\t// with the ingest capability (or full access). Each handler binds the\n\t\t// operation to a single (move: source+target) KB and rejects any KB\n\t\t// or knowledge id outside the key's allow-list, so a scoped ingest key\n\t\t// can only touch KBs it is already permitted to write.\n\t\tk.PUT(\"/tags\", g.Contributor(), handler.UpdateKnowledgeTagBatch)\n\t\tk.POST(\"/batch-reparse\", g.Contributor(), handler.BatchReparseKnowledge)\n\t\tk.POST(\"/batch-delete\", g.Contributor(), handler.BatchDeleteKnowledge)\n\t\tk.POST(\"/folder\", g.Contributor(), handler.MoveKnowledgeToFolder)\n\t\tk.POST(\"/move\", g.Contributor(), handler.MoveKnowledge)\n\t}\n}\n\n// RegisterFAQRoutes 注册 FAQ 相关路由\n//\n// FAQ entries are KB content: reads are Viewer+, all mutations\n// (create / update / upsert / delete / batch field+tag updates,\n// import display flag) are Contributor+. Search is read-only.\nfunc RegisterFAQRoutes(r *gin.RouterGroup, handler *handler.FAQHandler, g *rbacGuards) {\n\tif handler == nil {\n\t\treturn\n\t}\n\t// FAQ entries 是 KB 的子资源（FAQ-type KB 的内容主体）。修改 FAQ\n\t// 等价于修改 KB 内容，必须遵循 KB 的\"creator OR Admin+\"矩阵 ——\n\t// 跟 chunks / wiki pages 保持一致。Viewer+ 可以读，Contributor 不能\n\t// 改不属于自己的 KB 的 FAQ。\n\tfaq := g.apiKeyGroup(r.Group(\"/knowledge-bases/:id/faq\"), apiKeyIngest(apiKeyFullAccess()))\n\tfaqRead := faq.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\t// KBAccessRead/Write resolve own/shared/agent-visible access and\n\t\t// rewrite the request's tenant context — handler no longer\n\t\t// carries an effectiveCtxForKB helper.\n\t\tfaqRead.GET(\"/entries\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListEntries)\n\t\tfaqRead.GET(\"/entries/export\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ExportEntries)\n\t\tfaqRead.GET(\"/entries/:entry_id\", g.Viewer(), g.KBAccessRead(\"id\"), handler.GetEntry)\n\t\tfaq.POST(\"/entries\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpsertEntries)\n\t\tfaq.PATCH(\"/entries\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.PatchEntriesBatch)\n\t\tfaq.POST(\"/entry\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.CreateEntry)\n\t\tfaq.PUT(\"/entries/:entry_id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpdateEntry)\n\t\tfaq.POST(\"/entries/:entry_id/similar-questions\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.AddSimilarQuestions)\n\t\t// Unified batch update API - supports is_enabled, is_recommended, tag_id\n\t\tfaq.PUT(\"/entries/fields\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpdateEntryFieldsBatch)\n\t\tfaq.PUT(\"/entries/tags\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpdateEntryTagBatch)\n\t\tfaq.DELETE(\"/entries\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.DeleteEntries)\n\t\t// Search is a read route: scoped API keys may call it with retrieve\n\t\t// even though POST is otherwise an unsafe method.\n\t\tfaqRead.POST(\"/search\", g.Viewer(), g.KBAccessRead(\"id\"), handler.SearchFAQ)\n\t\t// FAQ import result display status\n\t\tfaq.PUT(\"/import/last-result/display\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpdateLastImportResultDisplayStatus)\n\t}\n\t// FAQ import progress route (outside of knowledge-base scope) — Viewer+.\n\t// Scoped API keys that can ingest (they start the import) or retrieve may\n\t// poll their own import/dry-run progress. The task is tenant-scoped by\n\t// requireTaskProgressTenant, so a key only ever sees its own tenant's\n\t// tasks. Declared through apiKeyRoute so the APIKeyGate doesn't fail-closed\n\t// and 403 the poller with \"scope does not allow this operation\".\n\tg.apiKeyRoute(r, http.MethodGet, \"/faq/import/progress/:task_id\",\n\t\tapiKeyRetrieve(apiKeyIngest(apiKeyFullAccess())), g.Viewer(), handler.GetImportProgress)\n}\n\n// RegisterKnowledgeBaseRoutes 注册知识库相关的路由\nfunc RegisterKnowledgeBaseRoutes(r *gin.RouterGroup, handler *handler.KnowledgeBaseHandler, g *rbacGuards) {\n\t// 知识库路由组。API-key 可达性按能力分两档，全部通过 apiKeyGroup 声明，\n\t// 不要再用裸 kbgrp.Handle 注册（那会绕过网关、对所有 key 静默默认拒绝）：\n\t//\n\t//   1. 读取（list/detail/search/progress/move-targets）—— retrieve OR full-access（kb）\n\t//   2. KB 生命周期管理（create/copy/duplicate/update/delete）\n\t//      —— manage_kbs OR full-access（kbManagement）\n\t//\n\t// 第 2 档整条 KB 生命周期共用同一策略：manage_kbs 是「管理知识库」capability，\n\t// 建/拷/改/删都是它的分内事。KB 的 allow-list 仍在下游生效——copy/duplicate/\n\t// update/delete 的目标 KB 会被 allow-list 兜住；create 无源可约束，限定 allow-list\n\t// 的 key 建出的新 KB 落在其 allow-list 之外（同租户、无越权，只是建完自己管不到），\n\t// 空 allow-list 的 key 则是全租户 KB 管理、新建天然在范围内。KB 内容写入（文档/\n\t// 分块/FAQ/Tag/Wiki）由对应子路由的 ingest 能力控制，不在本组。\n\tkbgrp := r.Group(\"/knowledge-bases\")\n\tkb := g.apiKeyGroup(kbgrp, apiKeyRetrieve(apiKeyFullAccess()))\n\tkbManagement := kb.With(apiKeyManageKnowledgeBases(apiKeyFullAccess()))\n\t{\n\t\t// 创建知识库 — JWT Contributor+；API key 需 manage_kbs 或 full-access。\n\t\tkbManagement.POST(\"\", g.Contributor(), handler.CreateKnowledgeBase)\n\t\t// 获取知识库列表 — Viewer+ for JWT callers; retrieve-capable API keys pass via the gate.\n\t\tkb.GET(\"\", g.Viewer(), handler.ListKnowledgeBases)\n\t\t// 获取知识库详情 — Viewer+ 且对 KB 有 read 权限\n\t\tkb.GET(\"/:id\", g.Viewer(), g.KBAccessRead(\"id\"), handler.GetKnowledgeBase)\n\t\t// 更新/删除知识库 — 两层正交鉴权，缺一不可：\n\t\t//   OwnedKBOrAdmin  管「租户内」归属：非创建者的 Contributor 改不了\n\t\t//                   同事的 KB（跨租户 KB 在此走 lookup=NotFound → 交给\n\t\t//                   下游处理，不在此拦）。\n\t\t//   KBAccessWrite   管「跨租户」访问级：自有 KB 或被组织共享(editor)。\n\t\t// handler 内再按 permission/所有者租户做最终判定 —— 尤其 DeleteKnowledgeBase\n\t\t// 以调用者「自身」租户(c.Keys，未被 KBAccess 改写)校验 kb.TenantID，\n\t\t// 把删除锁死为「所有者租户 + Admin」，共享 editor 无法删除源 KB。\n\t\tkbManagement.PUT(\"/:id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpdateKnowledgeBase)\n\t\tkbManagement.PATCH(\"/:id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.PatchKnowledgeBase)\n\t\t// 立即重新生成知识库 AI 描述 — 与更新知识库同档鉴权；同步执行一次小模型调用。\n\t\tkbManagement.POST(\"/:id/profile/generate\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"),\n\t\t\thandler.GenerateKnowledgeBaseProfile)\n\t\tkbManagement.DELETE(\"/:id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.DeleteKnowledgeBase)\n\t\t// 置顶/取消置顶知识库 — 创建者本人 OR Admin+ 且对 KB 有 write 权限\n\t\t// Pin state is now per-(user, kb) (migration 000050). Anyone with\n\t\t// at least Viewer-level read access to the KB — including users\n\t\t// who reached it via a shared agent — may pin it for themselves;\n\t\t// no edit permission is required. The OwnedKBOrAdmin guard was\n\t\t// removed accordingly. The route still requires KB read access\n\t\t// so callers can't poke at KBs they can't see.\n\t\tkb.PUT(\"/:id/pin\", g.Viewer(), g.KBAccessRead(\"id\"), handler.TogglePinKnowledgeBase)\n\t\t// 混合搜索 — Viewer+ 且对 KB 有 read 权限 (read-only)\n\t\t// POST is preferred; GET with JSON body is kept for backward compatibility (#1727).\n\t\tkb.POST(\"/:id/hybrid-search\", g.Viewer(), g.KBAccessRead(\"id\"), handler.HybridSearch)\n\t\tkb.GET(\"/:id/hybrid-search\", g.Viewer(), g.KBAccessRead(\"id\"), handler.HybridSearch)\n\t\t// 拷贝知识库 — 产出新 KB，与 create 同档：JWT Contributor+，API key 需 manage_kbs 或 full-access。\n\t\t// 源 KB 通过 body 里的 source_id 传入（非 :id 路径参数），无法套用基于路径参数\n\t\t// 的 KBAccessRead，故源/目标 KB 的租户归属与 allow-list 校验在 handler 内完成\n\t\t// （requireTenantAPIKeyKnowledgeBases 会把 source_id/target_id 兜进 allow-list）。\n\t\t// 副本归调用者所有，不需要原 KB 的所有权。\n\t\tkbManagement.POST(\"/copy\", g.Contributor(), handler.CopyKnowledgeBase)\n\t\t// 创建知识库副本 — 产出新 KB，与 create 同档：JWT Contributor+，API key 需 manage_kbs 或 full-access；\n\t\t// 且对源 KB 有 read 权限（KBAccessRead 会对限定 key 兜住源 KB）。只创建新的 KB 设置记录，不复制内容/索引/分享。\n\t\tkbManagement.POST(\"/:id/duplicate\", g.Contributor(), g.KBAccessRead(\"id\"), handler.DuplicateKnowledgeBase)\n\t\t// 获取知识库复制进度 — Viewer+；只读。manage_kbs（发起 copy 的 key）或\n\t\t// retrieve 均可轮询；任务按租户隔离（requireTaskProgressTenant），key 只能\n\t\t// 查本租户任务。\n\t\tkb.With(apiKeyRetrieve(apiKeyManageKnowledgeBases(apiKeyFullAccess()))).\n\t\t\tGET(\"/copy/progress/:task_id\", g.Viewer(), handler.GetKBCloneProgress)\n\t\t// 获取可移动目标知识库列表 — Viewer+ 且对 KB 有 read 权限\n\t\tkb.GET(\"/:id/move-targets\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListMoveTargets)\n\t}\n}\n\n// RegisterImageAttrRoutes wires the global, read-only image-attribute registry\n// that drives the KB editor's attribute panel.\n//\n// The registry is a single source of truth, so adding an attribute is a\n// backend-only change (one registry row) and the UI follows automatically. It\n// carries no KB id and needs only the Viewer role, so — like the other\n// read-only KB-editor helpers GET /chunker/preview and GET\n// /system/parser-engines — it is mounted at the top level rather than under\n// the /knowledge-bases collection.\nfunc RegisterImageAttrRoutes(r *gin.RouterGroup, handler *handler.KnowledgeBaseHandler, g *rbacGuards) {\n\tg.apiKeyRoute(r, http.MethodGet, \"/image-attrs/schema\",\n\t\tapiKeyRetrieve(apiKeyFullAccess()), g.Viewer(), handler.GetImageAttrsSchema)\n\t// Same shape and the same audience as the schema above: a read-only list of\n\t// what the settings panel can offer, with no KB id, so the Viewer role is\n\t// enough. Mounted here rather than under /knowledge-bases because neither\n\t// the list nor a pipeline id is knowledge-base-specific.\n\tg.apiKeyRoute(r, http.MethodGet, \"/image-pipelines\",\n\t\tapiKeyRetrieve(apiKeyFullAccess()), g.Viewer(), handler.GetImagePipelines)\n\t// The settings panel asks this while the user edits, so that a combination\n\t// the pipeline cannot run is pointed out before the save rather than\n\t// rejected by it. Read-only, global, and answered from the pipeline's own\n\t// rules, so only the Viewer role is required.\n\tg.apiKeyRoute(r, http.MethodPost, \"/image-pipelines/validate\",\n\t\tapiKeyRetrieve(apiKeyFullAccess()), g.Viewer(), handler.ValidateImagePipelines)\n}\n\n// RegisterKnowledgeBaseActivityRoutes exposes the read-only per-KB activity\n// feed. It intentionally stays JWT-only: audit history is a sensitive owner\n// surface and no existing workspace API-key capability grants audit access.\nfunc RegisterKnowledgeBaseActivityRoutes(r *gin.RouterGroup, auditHandler *handler.AuditLogHandler, g *rbacGuards) {\n\tif auditHandler == nil {\n\t\treturn\n\t}\n\tr.GET(\"/knowledge-bases/:id/activity\",\n\t\tg.OwnedKBOrAdmin(), g.KBAccessRead(\"id\"), auditHandler.ListKnowledgeBaseActivity)\n}\n\n// RegisterKnowledgeTagRoutes 注册知识库标签相关路由。\n//\n// Tags are KB metadata: Viewer reads, Contributor writes. Per-KB\n// ownership granularity for tags is out of scope for PR 2; this is\n// purely role-based.\nfunc RegisterKnowledgeTagRoutes(r *gin.RouterGroup, tagHandler *handler.TagHandler, g *rbacGuards) {\n\tif tagHandler == nil {\n\t\treturn\n\t}\n\t// Tags 是 KB 的子资源 — 创建/编辑/删除标签会改变 KB 内容的检索分类\n\t// 行为，应该与 KB 主体的\"creator OR Admin+\"矩阵一致，避免一个无\n\t// 关 Contributor 在他人 KB 里乱建/删标签影响 KB owner 的内容组织。\n\tkbTags := g.apiKeyGroup(r.Group(\"/knowledge-bases/:id/tags\"), apiKeyIngest(apiKeyFullAccess()))\n\tkbTagsRead := kbTags.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\t// KBAccessRead/Write resolve own/shared/agent-visible access and\n\t\t// rewrite the request's tenant context to the effective tenant\n\t\t// for the duration of the handler — so the handler no longer\n\t\t// needs its own effectiveCtxForKB helper.\n\t\tkbTagsRead.GET(\"\", g.Viewer(), g.KBAccessRead(\"id\"), tagHandler.ListTags)\n\t\tkbTags.POST(\"\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), tagHandler.CreateTag)\n\t\tkbTags.PUT(\"/:tag_id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), tagHandler.UpdateTag)\n\t\tkbTags.DELETE(\"/:tag_id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), tagHandler.DeleteTag)\n\t}\n}\n\n// RegisterWikiPageRoutes registers wiki page related routes.\n//\n// Wiki pages are KB content (wiki mode): reads are Viewer+ and gated by\n// KBAccessRead (own / org-shared / via shared agent), matching FAQ /\n// chunk / tag read routes. Content mutations (create/update/delete) and\n// maintenance actions (rebuild-links, auto-fix, change issue status)\n// honour per-KB ownership via OwnedWikiKBOrAdmin (PR 5, #1303): the URL\n// :kb_id resolves directly to the owning KB so a Contributor who owns\n// the KB can manage its wiki, while a non-owner Contributor gets 403.\nfunc RegisterWikiPageRoutes(r *gin.RouterGroup, wikiHandler *handler.WikiPageHandler, g *rbacGuards) {\n\twiki := g.apiKeyGroup(r.Group(\"/knowledgebase/:kb_id/wiki\"), apiKeyIngest(apiKeyFullAccess()))\n\twikiRead := wiki.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\t// Page CRUD\n\t\twikiRead.GET(\"/pages\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.ListPages)\n\t\twiki.POST(\"/pages\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.CreatePage)\n\t\twiki.PUT(\"/move-page\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.MovePage)\n\t\twikiRead.GET(\"/pages/*slug\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.GetPage)\n\t\twiki.PUT(\"/pages/*slug\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.UpdatePage)\n\t\twiki.DELETE(\"/pages/*slug\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.DeletePage)\n\n\t\t// Revision history (slug is a catch-all like /pages; revert carries\n\t\t// the slug in the body for the same reason move-page does)\n\t\twikiRead.GET(\"/revisions/*slug\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.ListRevisions)\n\t\twiki.POST(\"/revert\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.RevertPage)\n\n\t\t// Folder tree (directory nodes)\n\t\twikiRead.GET(\"/folders\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.ListFolders)\n\t\twiki.POST(\"/folders\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.CreateFolder)\n\t\twiki.PUT(\"/folders/:folder_id\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.UpdateFolder)\n\t\twiki.DELETE(\"/folders/:folder_id\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.DeleteFolder)\n\n\t\t// Special pages\n\t\twikiRead.GET(\"/index\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.GetIndex)\n\n\t\t// Graph and stats\n\t\twikiRead.GET(\"/graph\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.GetGraph)\n\t\twikiRead.GET(\"/stats\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.GetStats)\n\n\t\t// Search and maintenance\n\t\twikiRead.GET(\"/search\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.SearchPages)\n\t\twiki.POST(\"/rebuild-links\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.RebuildLinks)\n\t\twikiRead.GET(\"/lint\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.Lint)\n\t\twiki.POST(\"/auto-fix\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.AutoFix)\n\n\t\t// Issues\n\t\twikiRead.GET(\"/issues\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.ListIssues)\n\t\twiki.PUT(\"/issues/:issue_id/status\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.UpdateIssueStatus)\n\t}\n\n\twikiSearch := g.apiKeyGroup(r.Group(\"/wiki-search\", g.Viewer()), apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\twikiSearch.POST(\"\", wikiHandler.SearchPagesAcross)\n\t}\n}\n"
    },
    {
      "path": "internal/handler/knowledgebase.go",
      "content": "package handler\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\tstderrors \"errors\"\n\t\"io\"\n\t\"maps\"\n\t\"net/http\"\n\t\"strconv\"\n\t\"strings\"\n\t\"time\"\n\n\t\"github.com/Tencent/WeKnora/internal/application/access\"\n\t\"github.com/Tencent/WeKnora/internal/application/repository\"\n\t\"github.com/Tencent/WeKnora/internal/application/service\"\n\t\"github.com/Tencent/WeKnora/internal/config\"\n\t\"github.com/Tencent/WeKnora/internal/errors\"\n\tapperrors \"github.com/Tencent/WeKnora/internal/errors\"\n\t\"github.com/Tencent/WeKnora/internal/logger\"\n\t\"github.com/Tencent/WeKnora/internal/middleware\"\n\t\"github.com/Tencent/WeKnora/internal/storageurl\"\n\t\"github.com/Tencent/WeKnora/internal/tracing/langfuse\"\n\t\"github.com/Tencent/WeKnora/internal/types\"\n\t\"github.com/Tencent/WeKnora/internal/types/interfaces\"\n\t\"github.com/Tencent/WeKnora/internal/utils\"\n\tsecutils \"github.com/Tencent/WeKnora/internal/utils\"\n\t\"github.com/gin-gonic/gin\"\n\t\"github.com/google/uuid\"\n\t\"github.com/hibiken/asynq\"\n)\n\n// KnowledgeBaseHandler defines the HTTP handler for knowledge base operations\ntype KnowledgeBaseHandler struct {\n\tcfg                *config.Config\n\tservice            interfaces.KnowledgeBaseService\n\tprofileService     interfaces.KnowledgeBaseProfileService\n\tknowledgeService   interfaces.KnowledgeService\n\tkbShareService     interfaces.KBShareService\n\tagentShareService  interfaces.AgentShareService\n\tasynqClient        interfaces.TaskEnqueuer\n\tvectorStoreService interfaces.VectorStoreService // enriches KB responses with bound store display\n\t// userService 仅在 list 类接口里用于批量回填 creator_name；\n\t// 真正的鉴权由 RBAC 中间件 + Lookup 完成，这里不参与决策。\n\tuserService interfaces.UserService\n\t// fileService and storageResolver back the optional `resource_urls=public`\n\t// mode on hybrid-search. Both may be nil in tests, in which case only the\n\t// default handle mode is available.\n\tfileService     interfaces.FileService\n\tstorageResolver interfaces.StorageBackendResolver\n}\n\n// NewKnowledgeBaseHandler creates a new knowledge base handler instance\nfunc NewKnowledgeBaseHandler(\n\tcfg *config.Config,\n\tservice interfaces.KnowledgeBaseService,\n\tknowledgeService interfaces.KnowledgeService,\n\tkbShareService interfaces.KBShareService,\n\tagentShareService interfaces.AgentShareService,\n\tasynqClient interfaces.TaskEnqueuer,\n\tvectorStoreService interfaces.VectorStoreService,\n\tuserService interfaces.UserService,\n\tfileService interfaces.FileService,\n\tstorageResolver interfaces.StorageBackendResolver,\n\tprofileService interfaces.KnowledgeBaseProfileService,\n) *KnowledgeBaseHandler {\n\treturn &KnowledgeBaseHandler{\n\t\tcfg:                cfg,\n\t\tprofileService:     profileService,\n\t\tservice:            service,\n\t\tknowledgeService:   knowledgeService,\n\t\tkbShareService:     kbShareService,\n\t\tagentShareService:  agentShareService,\n\t\tasynqClient:        asynqClient,\n\t\tvectorStoreService: vectorStoreService,\n\t\tuserService:        userService,\n\t\tfileService:        fileService,\n\t\tstorageResolver:    storageResolver,\n\t}\n}\n\n// resolveResourceRewriter builds the storage-reference rewriter for one response\n// from the request's `resource_urls` parameter, falling back to the deployment\n// default. The returned error is already an AppError the caller can hand to\n// c.Error: a rejected scope is a 403, a typo in the parameter is a 400.\nfunc (h *KnowledgeBaseHandler) resolveResourceRewriter(c *gin.Context) (*storageurl.Rewriter, error) {\n\tctx := c.Request.Context()\n\tmode, err := storageurl.ResolveMode(ctx, c.Query(storageurl.QueryParam))\n\tif err != nil {\n\t\tif stderrors.Is(err, storageurl.ErrPublicModeForbidden) {\n\t\t\treturn nil, apperrors.NewForbiddenError(err.Error())\n\t\t}\n\t\treturn nil, apperrors.NewBadRequestError(err.Error())\n\t}\n\treturn storageurl.NewRequestRewriter(ctx, mode, h.fileService, h.storageResolver), nil\n}\n\n// buildKBResponse turns a knowledge base into a JSON-ready response shape,\n// merging the bound vector store's display metadata and any caller-supplied\n// extras (e.g., my_permission for shared KBs). Returns the kb pointer\n// unchanged on serialization failure so the request still succeeds.\n//\n// The map-merge approach (rather than a wrapper struct embedding the kb)\n// is deliberate: KnowledgeBase has a custom MarshalJSON, and embedding\n// would promote it to any wrapper struct and silently swallow the extra\n// fields. The same pattern is already used by GetKnowledgeBase to add the\n// my_permission field for shared knowledge bases.\n//\n// Shared-KB suppression: when storeView.Source == StoreSourceShared (the\n// caller is not the KB owner), the raw vector_store_id UUID is stripped\n// from the response so the owner-tenant's store inventory cannot be\n// correlated across multiple shared KBs. Name / engine type / status are\n// already empty in the SharedStoreDisplay payload; suppressing the UUID\n// completes the cross-tenant metadata hiding.\nfunc buildKBResponse(\n\tkb *types.KnowledgeBase,\n\tstoreView types.StoreDisplay,\n\textras map[string]interface{},\n) interface{} {\n\tb, err := json.Marshal(kb)\n\tif err != nil {\n\t\treturn kb\n\t}\n\tvar m map[string]interface{}\n\tif err := json.Unmarshal(b, &m); err != nil || m == nil {\n\t\treturn kb\n\t}\n\tif storeView.Source == types.StoreSourceShared {\n\t\tdelete(m, \"vector_store_id\")\n\t}\n\tif storeView.Name != \"\" {\n\t\tm[\"vector_store_name\"] = storeView.Name\n\t}\n\tif storeView.Source != \"\" {\n\t\tm[\"vector_store_source\"] = storeView.Source\n\t}\n\tif storeView.EngineType != \"\" {\n\t\tm[\"vector_store_engine_type\"] = storeView.EngineType\n\t}\n\tif storeView.Status != \"\" {\n\t\tm[\"vector_store_status\"] = storeView.Status\n\t}\n\tfor k, v := range extras {\n\t\tm[k] = v\n\t}\n\treturn m\n}\n\n// buildKBListResponse turns a slice of knowledge bases into a JSON-ready\n// slice that mirrors the single-KB enrichment in buildKBResponse. Store\n// views are batch-resolved once via BatchResolveStoreView to keep the\n// list endpoint O(1) in vector-store service calls — the per-KB\n// resolveKBStoreView would otherwise be N+1.\n//\n// Caller-vs-owner semantics match the single-KB path:\n//   - KB has no binding         → DefaultStoreDisplay()\n//   - KB is owned by another tenant (cross-tenant shared) → SharedStoreDisplay()\n//   - KB is own-tenant bound    → look up in the batch result; misses\n//     fall back to UnavailableStoreDisplay()\n//\n// Resolver failures degrade gracefully: every own-tenant bound KB renders\n// as unavailable instead of breaking the list response.\nfunc (h *KnowledgeBaseHandler) buildKBListResponse(\n\tctx context.Context, kbs []*types.KnowledgeBase, callerTenantID uint64,\n) []interface{} {\n\tdefaultView := h.envDefaultStoreView(ctx)\n\tstoreViews := h.batchResolveKBStoreViews(ctx, kbs, callerTenantID)\n\tout := make([]interface{}, 0, len(kbs))\n\tfor _, kb := range kbs {\n\t\tvar view types.StoreDisplay\n\t\tswitch {\n\t\tcase !kb.HasVectorStore():\n\t\t\tview = defaultView\n\t\tcase kb.TenantID != callerTenantID:\n\t\t\tview = types.SharedStoreDisplay()\n\t\tdefault:\n\t\t\tv, ok := storeViews[*kb.VectorStoreID]\n\t\t\tif !ok || v.Source == \"\" {\n\t\t\t\tview = types.UnavailableStoreDisplay()\n\t\t\t} else {\n\t\t\t\tview = v\n\t\t\t}\n\t\t}\n\t\tout = append(out, buildKBResponse(kb, view, nil))\n\t}\n\treturn out\n}\n\n// sharedKBRow projects a SharedKnowledgeBaseInfo into a response payload\n// that respects the cross-tenant strip rule: the embedded KnowledgeBase\n// row runs through buildKBResponse with SharedStoreDisplay() so its\n// vector_store_id and any owner-tenant store metadata never reach the\n// wire. The share-record fields (share_id, organization_id, etc.) are\n// kept intact alongside the stripped KB. Callers can pass extras to\n// merge view-specific keys such as is_mine or source_from_agent.\n//\n// Always uses SharedStoreDisplay() regardless of whether the caller is\n// the owner; the cross-tenant share endpoints serve mixed audiences and\n// the owner's \"rich\" view of their own bindings is already served by\n// ListKnowledgeBases / single-KB GET on the standard knowledge-base\n// routes. Trying to enrich own-row entries here would either require\n// threading the vector-store service through the organization handler\n// or duplicating the lookup logic — both larger than the security fix\n// warrants and easy to follow up on once needed.\nfunc sharedKBRow(\n\tinfo *types.SharedKnowledgeBaseInfo, extras map[string]interface{},\n) map[string]interface{} {\n\tkbView := buildKBResponse(info.KnowledgeBase, types.SharedStoreDisplay(), nil)\n\trow := map[string]interface{}{\n\t\t\"knowledge_base\":   kbView,\n\t\t\"share_id\":         info.ShareID,\n\t\t\"organization_id\":  info.OrganizationID,\n\t\t\"org_name\":         info.OrgName,\n\t\t\"permission\":       info.Permission,\n\t\t\"source_tenant_id\": info.SourceTenantID,\n\t\t\"shared_at\":        info.SharedAt,\n\t}\n\tfor k, v := range extras {\n\t\trow[k] = v\n\t}\n\treturn row\n}\n\n// envDefaultStoreView returns the env-fallback store display enriched with\n// the configured env-store engine type when the service is available. The\n// service path populates EngineType so the caller can show \"postgres\" or\n// \"qdrant\" on the env-default badge instead of leaving it blank. A nil\n// service (e.g. in narrow unit-test setups) falls back to the bare default\n// display rather than failing the list response.\nfunc (h *KnowledgeBaseHandler) envDefaultStoreView(ctx context.Context) types.StoreDisplay {\n\tif h.vectorStoreService == nil {\n\t\treturn types.DefaultStoreDisplay()\n\t}\n\treturn h.vectorStoreService.EnvDefaultStoreView(ctx)\n}\n\n// batchResolveKBStoreViews collects the unique own-tenant store IDs across\n// the KB slice and resolves them in one BatchResolveStoreView call.\n// Cross-tenant shared KBs never enter the batch — they always render\n// via SharedStoreDisplay, which deliberately suppresses the owner\n// tenant's store name and engine type so cross-tenant viewers cannot\n// correlate the owner's store inventory from KB responses alone.\nfunc (h *KnowledgeBaseHandler) batchResolveKBStoreViews(\n\tctx context.Context, kbs []*types.KnowledgeBase, callerTenantID uint64,\n) map[string]types.StoreDisplay {\n\tif h.vectorStoreService == nil {\n\t\treturn nil\n\t}\n\tstoreIDs := make([]string, 0, len(kbs))\n\tseen := make(map[string]bool, len(kbs))\n\tfor _, kb := range kbs {\n\t\tif !kb.HasVectorStore() || kb.TenantID != callerTenantID {\n\t\t\tcontinue\n\t\t}\n\t\tsid := *kb.VectorStoreID\n\t\tif !seen[sid] {\n\t\t\tseen[sid] = true\n\t\t\tstoreIDs = append(storeIDs, sid)\n\t\t}\n\t}\n\tif len(storeIDs) == 0 {\n\t\treturn nil\n\t}\n\tviews, err := h.vectorStoreService.BatchResolveStoreView(ctx, callerTenantID, storeIDs)\n\tif err != nil {\n\t\tlogger.WarnWithFields(ctx, logger.Fields{\n\t\t\t\"tenant_id\":   callerTenantID,\n\t\t\t\"store_count\": len(storeIDs),\n\t\t}, \"[kb.list] batch store view resolve failed; rendering bound KBs as unavailable\")\n\t\treturn nil\n\t}\n\treturn views\n}\n\n// resolveKBStoreView returns the store display payload to embed in the KB\n// response. It applies two policies on top of the service-level resolver:\n//\n//   - When the KB does not have a DB-managed vector store binding,\n//     the env-fallback display is returned without touching the service.\n//   - When the caller is not the KB owner (shared access), the underlying\n//     store's name and engine are suppressed so operator-chosen names do\n//     not leak across tenants. The Source value is set to \"shared\".\n//\n// On resolution error, an unavailable display is returned and the failure\n// is logged for ops; the request itself still succeeds.\nfunc (h *KnowledgeBaseHandler) resolveKBStoreView(\n\tctx context.Context, kb *types.KnowledgeBase, callerTenantID uint64,\n) types.StoreDisplay {\n\tif !kb.HasVectorStore() {\n\t\treturn h.envDefaultStoreView(ctx)\n\t}\n\tif kb.TenantID != callerTenantID {\n\t\treturn types.SharedStoreDisplay()\n\t}\n\tif h.vectorStoreService == nil {\n\t\treturn types.UnavailableStoreDisplay()\n\t}\n\tview, err := h.vectorStoreService.ResolveStoreView(ctx, kb.TenantID, *kb.VectorStoreID)\n\tif err != nil {\n\t\tlogger.WarnWithFields(ctx, logger.Fields{\n\t\t\t\"kb_id\":     secutils.SanitizeForLog(kb.ID),\n\t\t\t\"tenant_id\": kb.TenantID,\n\t\t}, \"[kb.view] vector store resolve failed; returning unavailable\")\n\t\treturn types.UnavailableStoreDisplay()\n\t}\n\treturn view\n}\n\n// KnowledgeBaseJSON is the encoding/json form of a knowledge base: the struct\n// fields plus the computed capabilities object added by MarshalJSON.\n// Doc-only; handlers still serialize *types.KnowledgeBase directly.\ntype KnowledgeBaseJSON struct {\n\ttypes.KnowledgeBase\n\tCapabilities types.KBCapabilities `json:\"capabilities\"`\n}\n\n// KnowledgeBaseView is KnowledgeBaseJSON plus the optional vector-store\n// display fields buildKBResponse merges in. Shared responses omit\n// vector_store_id; owned responses include it via the embedded struct.\ntype KnowledgeBaseView struct {\n\tKnowledgeBaseJSON\n\tVectorStoreName       string `json:\"vector_store_name,omitempty\"`\n\tVectorStoreSource     string `json:\"vector_store_source,omitempty\"`\n\tVectorStoreEngineType string `json:\"vector_store_engine_type,omitempty\"`\n\tVectorStoreStatus     string `json:\"vector_store_status,omitempty\"`\n\t// MyPermission is the caller's role on a knowledge base shared from\n\t// another workspace; GET /knowledge-bases/{id} sets it.\n\tMyPermission string `json:\"my_permission,omitempty\" enums:\"admin,editor,viewer\" extensions:\"x-agent\"`\n}\n\n// HybridSearchResponse is the hybrid-search body. meta is set only when the\n// request enabled rerank.\ntype HybridSearchResponse struct {\n\tSuccess bool                  `json:\"success\" example:\"true\"`\n\tData    []*types.SearchResult `json:\"data\"`\n\tMeta    *types.RetrievalMeta  `json:\"meta,omitempty\"`\n}\n\n// DuplicateKnowledgeBaseData is the data object of POST /knowledge-bases/{id}/duplicate.\ntype DuplicateKnowledgeBaseData struct {\n\tSourceID      string            `json:\"source_id\" extensions:\"x-agent=source_knowledge_base_id\"`\n\tTargetID      string            `json:\"target_id\" extensions:\"x-agent=knowledge_base_id\"`\n\tMessage       string            `json:\"message\" extensions:\"x-agent\"`\n\tKnowledgeBase KnowledgeBaseView `json:\"knowledge_base\"`\n}\n\n// ImageAttrSchemaData is the data object of GET /image-attrs/schema.\ntype ImageAttrSchemaData struct {\n\tVersion        string                   `json:\"version\"`\n\tPrompt         string                   `json:\"prompt\"`\n\tAttributes     []types.AttrSpec         `json:\"attributes\"`\n\tDefaultActions types.ImageActionsConfig `json:\"default_actions\"`\n}\n\n// HybridSearch godoc\n// @Summary      混合搜索\n// @Description  底层召回：向量+关键词混合检索，默认不 rerank（可用 rerank 字段开启）；一般检索请用 /knowledge-search。推荐 POST，GET 带 JSON 体仅兼容旧客户端。\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        id             path      string             true   \"知识库ID\"  extensions(x-agent=knowledge_base_id)\n// @Param        request        body      types.SearchParams true   \"搜索参数\"\n// @Param        resource_urls  query     string  false  \"文件引用形式，public 返回可加载直链\"  Enums(handle, public)  default(handle)\n// @Success      200            {object}  handler.HybridSearchResponse  \"搜索结果\"\n// @Failure      400            {object}  errors.AppError               \"请求参数错误\"\n// @Failure      404            {object}  errors.AppError               \"知识库不存在\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @x-agent      {\"id\":\"knowledge_base.search\",\"risk\":\"probe\",\"method\":\"post\",\"max_items\":30}\n// @x-agent-hint \"Runs the raw vector and keyword recall of one knowledge base, without rerank, and returns the chunks it finds in rank order, so you can see why something is or is not found. match_type 0 is a vector hit, 1 a keyword hit; score ranks the merged results and is not a similarity. Each threshold filters its own retriever before merging: leave them out to see every candidate, or set them to an agent's vector_threshold and keyword_threshold to see what passes. For answering a question, use search_knowledge instead.\"\n// @Router       /knowledge-bases/{id}/hybrid-search [post]\n// @Router       /knowledge-bases/{id}/hybrid-search [get]\nfunc (h *KnowledgeBaseHandler) HybridSearch(c *gin.Context) {\n\tctx := c.Request.Context()\n\n\tlogger.Info(ctx, \"Start hybrid search\")\n\n\t// Validate and check permission for knowledge base access\n\t_, id, effectiveTenantID, _, err := h.validateAndGetKnowledgeBase(c)\n\tif err != nil {\n\t\tc.Error(err)\n\t\treturn\n\t}\n\n\t// Parse request body\n\tlimitJSONBody(c, hybridSearchJSONMaxBytes)\n\tvar req types.SearchParams\n\tif err := c.ShouldBindJSON(&req); err != nil {\n\t\tif isRequestBodyTooLarge(err) {\n\t\t\t_ = c.Error(apperrors.NewBadRequestError(\"request body is too large\"))\n\t\t\treturn\n\t\t}\n\t\tlogger.Error(ctx, \"Failed to parse request parameters\", err)\n\t\tc.Error(apperrors.NewBadRequestError(\"Invalid request parameters\").WithDetails(err.Error()))\n\t\treturn\n\t}\n\tprecomputedVectorOnly := len(req.QueryEmbedding) > 0 && req.DisableKeywordsMatch && !req.DisableVectorMatch\n\tif strings.TrimSpace(req.QueryText) == \"\" && !precomputedVectorOnly {\n\t\t_ = c.Error(apperrors.NewBadRequestError(\"query_text is required\"))\n\t\treturn\n\t}\n\tif err := req.Rerank.Validate(); err != nil {\n\t\t_ = c.Error(apperrors.NewBadRequestError(err.Error()))\n\t\treturn\n\t}\n\tif req.Rerank.IsEnabled() && strings.TrimSpace(req.QueryText) == \"\" {\n\t\t// The rerank model scores passages against the query text.\n\t\t_ = c.Error(apperrors.NewBadRequestError(\"query_text is required when rerank is enabled\"))\n\t\treturn\n\t}\n\n\tlogger.Infof(ctx, \"Executing hybrid search, knowledge base ID: %s, query: %s, effectiveTenantID: %d\",\n\t\tsecutils.SanitizeForLog(id), secutils.SanitizeForLog(req.QueryText), effectiveTenantID)\n\n\t// Resolve before retrieving so a typo or a rejected scope costs nothing.\n\trewriter, err := h.resolveResourceRewriter(c)\n\tif err != nil {\n\t\tlogger.Warnf(ctx, \"Rejected resource URL mode: %v\", err)\n\t\t_ = c.Error(err)\n\t\treturn\n\t}\n\n\t// Execute hybrid search. Without a rerank object this is the raw recall\n\t// primitive it has always been; with one, the response carries meta.\n\t// Note: For shared KBs, the service uses effectiveTenantID internally via context\n\tvar retrieval *types.RetrievalResult\n\tif req.Rerank != nil {\n\t\tretrieval, err = h.service.HybridSearchWithRerank(c.Request.Context(), id, req)\n\t} else {\n\t\tvar results []*types.SearchResult\n\t\tresults, err = h.service.HybridSearch(c.Request.Context(), id, req)\n\t\tretrieval = &types.RetrievalResult{Results: results}\n\t}\n\tif err != nil {\n\t\t// Service-layer typed AppErrors (e.g. ErrVectorStoreBindingInvalid,\n\t\t// ErrVectorStoreUnavailable, BadRequest from multi-store fan-out)\n\t\t// must reach the client with their original code rather than be\n\t\t// downgraded to InternalServerError. Mirrors the pattern used in\n\t\t// CreateKnowledgeBase.\n\t\tif appErr, ok := apperrors.IsAppError(err); ok {\n\t\t\tc.Error(appErr)\n\t\t\treturn\n\t\t}\n\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\tc.Error(apperrors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\n\tlogger.Infof(ctx, \"Hybrid search completed, knowledge base ID: %s, result count: %d\",\n\t\tsecutils.SanitizeForLog(id), len(retrieval.Results))\n\tresponse := gin.H{\n\t\t\"success\": true,\n\t\t\"data\":    rewriter.CopyReferences(ctx, retrieval.Results),\n\t}\n\tif retrieval.Meta.Rerank != nil {\n\t\tresponse[\"meta\"] = retrieval.Meta\n\t}\n\tc.JSON(http.StatusOK, response)\n}\n\n// CreateKnowledgeBase godoc\n// @Summary      创建知识库\n// @Description  创建新的知识库\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        request  body      types.KnowledgeBase  true  \"知识库信息\"\n// @Success      201      {object}  handler.DataResponse{data=handler.KnowledgeBaseView}  \"创建的知识库\"\n// @Failure      400      {object}  errors.AppError                                      \"请求参数错误\"\n// @Failure      500      {object}  errors.AppError                                      \"服务器错误\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @x-agent      {\"id\":\"knowledge_base.create\",\"risk\":\"write\",\"label_param\":\"name\"}\n// @x-agent-hint \"Creates a knowledge base owned by the user. Omit type for document. Omit indexing flags for vector and keyword search. Set embedding_model_id and summary_model_id from model.list. vector_store_id can be chosen only now. A field you leave out keeps its default.\"\n// @Router       /knowledge-bases [post]\nfunc (h *KnowledgeBaseHandler) CreateKnowledgeBase(c *gin.Context) {\n\tctx := c.Request.Context()\n\n\tlogger.Info(ctx, \"Start creating knowledge base\")\n\n\t// Parse request body\n\tlimitJSONBody(c, knowledgeBaseJSONMaxBytes)\n\tbody, err := io.ReadAll(c.Request.Body)\n\tif err != nil {\n\t\tif isRequestBodyTooLarge(err) {\n\t\t\t_ = c.Error(apperrors.NewBadRequestError(\"request body is too large\"))\n\t\t\treturn\n\t\t}\n\t\t_ = c.Error(apperrors.NewBadRequestError(\"Invalid request parameters\").WithDetails(err.Error()))\n\t\treturn\n\t}\n\tvar req types.KnowledgeBase\n\tif err := json.Unmarshal(body, &req); err != nil {\n\t\tlogger.Error(ctx, \"Failed to parse request parameters\", err)\n\t\t_ = c.Error(apperrors.NewBadRequestError(\"Invalid request parameters\").WithDetails(err.Error()))\n\t\treturn\n\t}\n\treq.Name = strings.TrimSpace(req.Name)\n\tif req.Name == \"\" {\n\t\t_ = c.Error(apperrors.NewBadRequestError(\"name cannot be empty\"))\n\t\treturn\n\t}\n\t// A partial indexing_strategy must not turn the omitted pipelines off.\n\t// Missing flags keep the defaults: vector and keyword on, wiki and graph off.\n\tfillOmittedIndexingFlags(body, &req)\n\tif err := validateExtractConfig(req.ExtractConfig); err != nil {\n\t\tlogger.Error(ctx, \"Invalid extract configuration\", err)\n\t\tc.Error(err)\n\t\treturn\n\t}\n\ttypes.NormalizeKnowledgeBasePromptInstructions(&req)\n\tif err := validateKnowledgeBasePromptInstructions(&req); err != nil {\n\t\tc.Error(err)\n\t\treturn\n\t}\n\tprovider := strings.ToLower(strings.TrimSpace(req.GetStorageProvider()))\n\tif provider != \"\" && !isStorageProviderAllowed(provider) {\n\t\tc.Error(apperrors.NewBadRequestError(\"Storage provider is not allowed by STORAGE_ALLOW_LIST\"))\n\t\treturn\n\t}\n\n\tlogger.Infof(ctx, \"Creating knowledge base, name: %s\", secutils.SanitizeForLog(req.Name))\n\t// Create knowledge base using the service\n\tkb, err := h.service.CreateKnowledgeBase(ctx, &req)\n\tif err != nil {\n\t\t// Surface typed AppErrors (notably the 400-class codes\n\t\t// ErrVectorStoreBindingInvalid and ErrVectorStoreUnavailable\n\t\t// returned by validateVectorStoreBinding) instead of wrapping them\n\t\t// into a generic 500. The middleware renders the original code and\n\t\t// HTTP status verbatim. Falls through to 500 only for raw infra\n\t\t// errors that the service did not classify.\n\t\tif appErr, ok := apperrors.IsAppError(err); ok {\n\t\t\tc.Error(appErr)\n\t\t\treturn\n\t\t}\n\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\tc.Error(apperrors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\n\tlogger.Infof(ctx, \"Knowledge base created successfully, ID: %s, name: %s\",\n\t\tsecutils.SanitizeForLog(kb.ID), secutils.SanitizeForLog(kb.Name))\n\tcallerTenantID := c.GetUint64(types.TenantIDContextKey.String())\n\tc.JSON(http.StatusCreated, gin.H{\n\t\t\"success\": true,\n\t\t\"data\":    buildKBResponse(kb, h.resolveKBStoreView(ctx, kb, callerTenantID), nil),\n\t})\n}\n\n// validateAndGetKnowledgeBase validates request parameters and retrieves the knowledge base.\n// Enforces per-API-key KB scope before tenant/share/agent resolution.\n// Returns the knowledge base, knowledge base ID, effective tenant ID for embedding, permission level, and any errors encountered\n// For owned KBs, effectiveTenantID is the caller's tenant ID\n// For shared KBs, effectiveTenantID is the source tenant ID (owner's tenant)\nfunc (h *KnowledgeBaseHandler) validateAndGetKnowledgeBase(\n\tc *gin.Context,\n) (*types.KnowledgeBase, string, uint64, types.OrgMemberRole, error) {\n\tid := secutils.SanitizeForLog(c.Param(\"id\"))\n\tgrant, err := resolveHandlerKBAccess(c, id, h.service, h.kbShareService, h.agentShareService)\n\tif err != nil {\n\t\treturn nil, id, 0, \"\", err\n\t}\n\treturn grant.KnowledgeBase, id, grant.EffectiveTenantID, grant.Permission, nil\n}\n\n// GetKnowledgeBase godoc\n// @Summary      获取知识库详情\n// @Description  根据ID获取知识库详情。当使用共享智能体时，可传 agent_id 以校验该智能体是否有权访问该知识库。\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        id         path      string  true   \"知识库ID\"  extensions(x-agent=knowledge_base_id)\n// @Param        agent_id   query     string  false  \"共享智能体 ID（用于校验智能体是否有权访问该知识库）\"\n// @Success      200  {object}  handler.DataResponse{data=handler.KnowledgeBaseView}  \"知识库详情\"\n// @Failure      400  {object}  errors.AppError  \"请求参数错误\"\n// @Failure      403  {object}  errors.AppError  \"无权访问知识库\"\n// @Failure      404  {object}  errors.AppError  \"知识库不存在\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @x-agent      {\"id\":\"knowledge_base.get\",\"risk\":\"read\"}\n// @x-agent-hint \"Check which indexes are enabled (vector, keyword, Wiki, graph) and whether documents are processing.\"\n// @Router       /knowledge-bases/{id} [get]\nfunc (h *KnowledgeBaseHandler) GetKnowledgeBase(c *gin.Context) {\n\t// Validate and get the knowledge base\n\tkb, _, _, permission, err := h.validateAndGetKnowledgeBase(c)\n\tif err != nil {\n\t\tc.Error(err)\n\t\treturn\n\t}\n\t// Fill counts (knowledge_count, chunk_count, is_processing) so hover/detail shows correct numbers\n\tif fillErr := h.service.FillKnowledgeBaseCounts(c.Request.Context(), kb); fillErr != nil {\n\t\tlogger.Warnf(c.Request.Context(), \"Failed to fill KB counts for %s: %v\", kb.ID, fillErr)\n\t}\n\ttenantID := c.GetUint64(types.TenantIDContextKey.String())\n\tstoreView := h.resolveKBStoreView(c.Request.Context(), kb, tenantID)\n\tvar extras map[string]interface{}\n\tif kb.TenantID != tenantID && permission != \"\" {\n\t\t// Include my_permission in data so frontend can show role (e.g. \"只读\") instead of \"--\" for agent-visible KBs\n\t\textras = map[string]interface{}{\"my_permission\": permission}\n\t}\n\tc.JSON(http.StatusOK, gin.H{\"success\": true, \"data\": buildKBResponse(kb, storeView, extras)})\n}\n\n// ListKnowledgeBases godoc\n// @Summary      获取知识库列表\n// @Description  获取当前空间的所有知识库；或当传入 agent_id（共享智能体）时，校验权限后返回该智能体配置的知识库范围（用于 @ 提及）\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        agent_id  query     string  false  \"共享智能体 ID（传入时返回该智能体可用的知识库）\"\n// @Param        creator   query     string  false  \"按创建者过滤，仅 mine 与 others 生效\"  Enums(mine, others)\n// @Success      200       {object}  handler.DataResponse{data=[]handler.KnowledgeBaseView}  \"知识库列表\"\n// @Failure      400       {object}  errors.AppError                                         \"请求参数错误\"\n// @Failure      500       {object}  errors.AppError                                         \"服务器错误\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @x-agent      {\"id\":\"knowledge_base.list\",\"risk\":\"read\",\"max_items\":200}\n// @x-agent-hint \"The workspace's own knowledge bases, up to 200. Ones shared from other workspaces are in knowledge_base.list_shared.\"\n// @Router       /knowledge-bases [get]\nfunc (h *KnowledgeBaseHandler) ListKnowledgeBases(c *gin.Context) {\n\tctx := c.Request.Context()\n\n\tagentID := c.Query(\"agent_id\")\n\tif agentID != \"\" {\n\t\tagent, err := resolveSharedAgentForRequest(c, agentID, h.agentShareService)\n\t\tif err != nil {\n\t\t\t_ = c.Error(err)\n\t\t\treturn\n\t\t}\n\t\tcurrentTenantID := middleware.KBAccessRequest(c).Caller.TenantID\n\t\tscope := types.NewSharedAgentKBScope(agent)\n\t\tif scope.IsEmpty() {\n\t\t\tc.JSON(http.StatusOK, gin.H{\"success\": true, \"data\": []interface{}{}})\n\t\t\treturn\n\t\t}\n\t\tkbs, err := h.service.ListKnowledgeBasesByTenantID(ctx, agent.TenantID)\n\t\tif err != nil {\n\t\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\t\tc.Error(apperrors.NewInternalServerError(err.Error()))\n\t\t\treturn\n\t\t}\n\t\tkbs = filterKnowledgeBasesForSharedAgent(kbs, agent)\n\t\tkbs = filterKnowledgeBasesForAPIKeyScope(ctx, kbs)\n\n\t\tc.JSON(http.StatusOK, gin.H{\n\t\t\t\"success\": true,\n\t\t\t\"data\":    h.buildKBListResponse(ctx, kbs, currentTenantID),\n\t\t})\n\t\treturn\n\t}\n\n\t// Get all knowledge bases for this tenant\n\tkbs, err := h.service.ListKnowledgeBases(ctx)\n\tif err != nil {\n\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\tc.Error(apperrors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\n\t// Optional creator filter — drives the [All | Mine | Others] segmented\n\t// control on the list page. We filter in-process rather than pushing\n\t// down into SQL because the tenant-bounded KB list is small (typically\n\t// <100 rows) and adding a creator predicate to ListKnowledgeBases would\n\t// ripple through every other caller (chat pipeline, agent editor, …).\n\t// Rows with empty CreatorID predate the RBAC migration (PR 5); we treat\n\t// them as \"not anyone in particular\" so they never appear under \"mine\"\n\t// or \"others\" — they fall out of both filters cleanly.\n\tcreatorFilter := strings.ToLower(strings.TrimSpace(c.Query(\"creator\")))\n\tif creatorFilter == \"mine\" || creatorFilter == \"others\" {\n\t\tcallerUserID, _ := c.Get(types.UserIDContextKey.String())\n\t\tcallerUserIDStr, _ := callerUserID.(string)\n\t\tfiltered := make([]*types.KnowledgeBase, 0, len(kbs))\n\t\tfor _, kb := range kbs {\n\t\t\tif kb.CreatorID == \"\" {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tif creatorFilter == \"mine\" && kb.CreatorID == callerUserIDStr {\n\t\t\t\tfiltered = append(filtered, kb)\n\t\t\t} else if creatorFilter == \"others\" && kb.CreatorID != callerUserIDStr {\n\t\t\t\tfiltered = append(filtered, kb)\n\t\t\t}\n\t\t}\n\t\tkbs = filtered\n\t}\n\tkbs = filterKnowledgeBasesForAPIKeyScope(ctx, kbs)\n\n\t// Get share counts for all knowledge bases\n\tif len(kbs) > 0 && h.kbShareService != nil {\n\t\tkbIDs := make([]string, len(kbs))\n\t\tfor i, kb := range kbs {\n\t\t\tkbIDs[i] = kb.ID\n\t\t}\n\n\t\tshareCounts, err := h.kbShareService.CountSharesByKnowledgeBaseIDs(ctx, kbIDs)\n\t\tif err != nil {\n\t\t\tlogger.Warnf(ctx, \"Failed to get share counts: %v\", err)\n\t\t} else {\n\t\t\tfor _, kb := range kbs {\n\t\t\t\tif count, ok := shareCounts[kb.ID]; ok {\n\t\t\t\t\tkb.ShareCount = count\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 批量回填 creator_name，让前端列表能区分「我创建」与「同空间其他成员创建」。\n\t// 仅在 list 接口里回填，详情 / 编辑场景不依赖这个字段；解析失败（用户已删除、\n\t// CreatorID 为空的老数据）就让字段为空，前端按 fallback 渲染。\n\tenrichKBCreatorNames(ctx, h.userService, kbs)\n\n\tcallerTenantID := c.GetUint64(types.TenantIDContextKey.String())\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"data\":    h.buildKBListResponse(ctx, kbs, callerTenantID),\n\t})\n}\n\nfunc filterKnowledgeBasesForAPIKeyScope(ctx context.Context, kbs []*types.KnowledgeBase) []*types.KnowledgeBase {\n\tscope, ok := types.TenantAPIKeyScopeFromContext(ctx)\n\tif !ok || len(scope.KnowledgeBaseIDs) == 0 {\n\t\treturn kbs\n\t}\n\tfiltered := make([]*types.KnowledgeBase, 0, len(kbs))\n\tfor _, kb := range kbs {\n\t\tif kb != nil && scope.AllowsKnowledgeBase(kb.ID) {\n\t\t\tfiltered = append(filtered, kb)\n\t\t}\n\t}\n\treturn filtered\n}\n\n// enrichKBCreatorNames 把 KB 列表里的 CreatorID 批量解析成展示名（username\n// 优先，退化到 email）。任意一步失败都吞掉错误：creator_name 缺失只会影响\n// 卡片右下角的徽章展示，不该影响列表本身可用。\nfunc enrichKBCreatorNames(ctx context.Context, userSvc interfaces.UserService, kbs []*types.KnowledgeBase) {\n\tif userSvc == nil || len(kbs) == 0 {\n\t\treturn\n\t}\n\tidSet := make(map[string]struct{}, len(kbs))\n\tfor _, kb := range kbs {\n\t\tif kb.CreatorID != \"\" {\n\t\t\tidSet[kb.CreatorID] = struct{}{}\n\t\t}\n\t}\n\tif len(idSet) == 0 {\n\t\treturn\n\t}\n\tids := make([]string, 0, len(idSet))\n\tfor id := range idSet {\n\t\tids = append(ids, id)\n\t}\n\tusers, err := userSvc.GetUsersByIDs(ctx, ids)\n\tif err != nil {\n\t\tlogger.Warnf(ctx, \"Failed to resolve KB creator names: %v\", err)\n\t\treturn\n\t}\n\tfor _, kb := range kbs {\n\t\tif kb.CreatorID == \"\" {\n\t\t\tcontinue\n\t\t}\n\t\tu, ok := users[kb.CreatorID]\n\t\tif !ok || u == nil {\n\t\t\tcontinue\n\t\t}\n\t\tkb.CreatorName = pickUserDisplayName(u)\n\t}\n}\n\n// pickUserDisplayName picks the field most users will recognise: Username\n// if present (it's required at registration), Email as a fallback. Used by\n// both KB and Agent list enrichment so the badge text stays consistent.\nfunc pickUserDisplayName(u *types.User) string {\n\tif u == nil {\n\t\treturn \"\"\n\t}\n\tif u.Username != \"\" {\n\t\treturn u.Username\n\t}\n\treturn u.Email\n}\n\n// TogglePinKnowledgeBase godoc\n// @Summary      置顶/取消置顶知识库\n// @Description  切换知识库的置顶状态\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        id  path      string  true  \"知识库ID\"\n// @Success      200  {object}  handler.DataResponse{data=handler.KnowledgeBaseView}  \"更新后的知识库\"\n// @Failure      400  {object}  errors.AppError                                      \"请求参数错误\"\n// @Failure      404  {object}  errors.AppError                                      \"知识库不存在\"\n// @Failure      500  {object}  errors.AppError                                      \"服务器错误\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @Router       /knowledge-bases/{id}/pin [put]\nfunc (h *KnowledgeBaseHandler) TogglePinKnowledgeBase(c *gin.Context) {\n\tctx := c.Request.Context()\n\tid := c.Param(\"id\")\n\tif id == \"\" {\n\t\tc.Error(apperrors.NewBadRequestError(\"knowledge base ID is required\"))\n\t\treturn\n\t}\n\n\tkb, err := h.service.TogglePinKnowledgeBase(ctx, id)\n\tif err != nil {\n\t\tif stderrors.Is(err, repository.ErrKnowledgeBaseNotFound) {\n\t\t\tc.Error(apperrors.NewNotFoundError(\"knowledge base not found\"))\n\t\t\treturn\n\t\t}\n\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\tc.Error(apperrors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\n\tcallerTenantID := c.GetUint64(types.TenantIDContextKey.String())\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"data\":    buildKBResponse(kb, h.resolveKBStoreView(ctx, kb, callerTenantID), nil),\n\t})\n}\n\n// UpdateKnowledgeBaseRequest defines the request body structure for updating a knowledge base\ntype UpdateKnowledgeBaseRequest struct {\n\tName        string                     `json:\"name\"        binding:\"required\"`\n\tDescription string                     `json:\"description\"`\n\tConfig      *types.KnowledgeBaseConfig `json:\"config\"`\n\t// VLMConfig updates the knowledge base's multimodal (vision) config.\n\t// Optional: nil means \"no change\", mirroring how CreateKnowledgeBase\n\t// accepts a top-level vlm_config.\n\tVLMConfig             *types.VLMConfig `json:\"vlm_config\"`\n\tquestionModelProvided bool\n}\n\n// UnmarshalJSON retains whether an older client supplied the question-model binding.\nfunc (r *UpdateKnowledgeBaseRequest) UnmarshalJSON(data []byte) error {\n\ttype plain UpdateKnowledgeBaseRequest\n\tif err := json.Unmarshal(data, (*plain)(r)); err != nil {\n\t\treturn err\n\t}\n\tvar payload struct {\n\t\tConfig struct {\n\t\t\tQuestions map[string]json.RawMessage `json:\"question_generation_config\"`\n\t\t} `json:\"config\"`\n\t}\n\tif err := json.Unmarshal(data, &payload); err != nil {\n\t\treturn err\n\t}\n\t_, r.questionModelProvided = payload.Config.Questions[\"model_id\"]\n\treturn nil\n}\n\n// UpdateKnowledgeBase godoc\n// @Summary      更新知识库\n// @Description  更新知识库的名称、描述和配置\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        id       path      string                     true  \"知识库ID\"\n// @Param        request  body      UpdateKnowledgeBaseRequest true  \"更新请求\"\n// @Success      200      {object}  handler.DataResponse{data=handler.KnowledgeBaseView}  \"更新后的知识库\"\n// @Failure      400      {object}  errors.AppError                                      \"请求参数错误\"\n// @Failure      403      {object}  errors.AppError                                      \"无权限\"\n// @Failure      404      {object}  errors.AppError                                      \"知识库不存在\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @Router       /knowledge-bases/{id} [put]\nfunc (h *KnowledgeBaseHandler) UpdateKnowledgeBase(c *gin.Context) {\n\tctx := c.Request.Context()\n\tlogger.Info(ctx, \"Start updating knowledge base\")\n\n\t// Validate and get the knowledge base\n\tcurrentKB, id, _, permission, err := h.validateAndGetKnowledgeBase(c)\n\tif err != nil {\n\t\tc.Error(err)\n\t\treturn\n\t}\n\n\t// Only admin/editor can update knowledge base\n\tif permission != types.OrgRoleAdmin && permission != types.OrgRoleEditor {\n\t\tc.Error(apperrors.NewForbiddenError(\"No permission to update knowledge base\"))\n\t\treturn\n\t}\n\n\t// Parse request body\n\tvar req UpdateKnowledgeBaseRequest\n\tif err := c.ShouldBindJSON(&req); err != nil {\n\t\tlogger.Error(ctx, \"Failed to parse request parameters\", err)\n\t\tc.Error(apperrors.NewBadRequestError(\"Invalid request parameters\").WithDetails(err.Error()))\n\t\treturn\n\t}\n\tif !req.questionModelProvided && req.Config != nil && req.Config.QuestionGenerationConfig != nil &&\n\t\tcurrentKB.QuestionGenerationConfig != nil {\n\t\treq.Config.QuestionGenerationConfig.ModelID = currentKB.QuestionGenerationConfig.ModelID\n\t}\n\tif err := validateKnowledgeBaseSettingsUpdate(c, currentKB, req.Config, req.VLMConfig); err != nil {\n\t\t_ = c.Error(err)\n\t\treturn\n\t}\n\tif req.Config != nil {\n\t\tprobe := &types.KnowledgeBase{\n\t\t\tChunkingConfig: req.Config.ChunkingConfig,\n\t\t\tWikiConfig:     req.Config.WikiConfig,\n\t\t\tProfileConfig:  req.Config.ProfileConfig,\n\t\t}\n\t\tif req.Config.ImageProcessingConfig != nil {\n\t\t\tprobe.ImageProcessingConfig = *req.Config.ImageProcessingConfig\n\t\t}\n\t\tif err := validateKnowledgeBasePromptInstructions(probe); err != nil {\n\t\t\tc.Error(err)\n\t\t\treturn\n\t\t}\n\t}\n\n\tlogger.Infof(ctx, \"Updating knowledge base, ID: %s, name: %s\",\n\t\tsecutils.SanitizeForLog(id), secutils.SanitizeForLog(req.Name))\n\n\t// Update the knowledge base\n\tkb, err := h.service.UpdateKnowledgeBase(ctx, id, req.Name, req.Description, req.Config, req.VLMConfig)\n\tif err != nil {\n\t\t// A rejected vlm_config is the caller's mistake, not a server failure.\n\t\tif appErr, ok := apperrors.IsAppError(err); ok {\n\t\t\t_ = c.Error(appErr)\n\t\t\treturn\n\t\t}\n\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\tc.Error(apperrors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\n\tcallerTenantID := c.GetUint64(types.TenantIDContextKey.String())\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"data\":    buildKBResponse(kb, h.resolveKBStoreView(ctx, kb, callerTenantID), nil),\n\t})\n}\n\n// validateKnowledgeBaseSettingsUpdate applies the same settings permissions to\n// PUT and PATCH. Shared editors may edit content, while model settings require\n// an admin share. Only the owner workspace may change the storage binding.\nfunc validateKnowledgeBaseSettingsUpdate(\n\tc *gin.Context, kb *types.KnowledgeBase, cfg *types.KnowledgeBaseConfig, vlm *types.VLMConfig,\n) error {\n\tsettings := vlm != nil || cfg != nil && (cfg.EmbeddingModelID != nil || cfg.SummaryModelID != nil ||\n\t\tcfg.StorageBackendID != nil || cfg.ASRConfig != nil ||\n\t\tquestionModelBindingChanged(kb, cfg.QuestionGenerationConfig))\n\tif !settings {\n\t\treturn nil\n\t}\n\townWorkspace, err := kbSettingsAccess(c, kb)\n\tif err != nil {\n\t\treturn err\n\t}\n\tif !ownWorkspace && cfg != nil && cfg.StorageBackendID != nil &&\n\t\tkbStorageBindingChanged(kb, *cfg.StorageBackendID, \"\") {\n\t\treturn apperrors.NewForbiddenError(\"只有知识库所属空间可以修改存储配置\")\n\t}\n\treturn nil\n}\n\nfunc questionModelBindingChanged(kb *types.KnowledgeBase, next *types.QuestionGenerationConfig) bool {\n\tif next == nil {\n\t\treturn false\n\t}\n\tprevious := \"\"\n\tif kb.QuestionGenerationConfig != nil {\n\t\tprevious = kb.QuestionGenerationConfig.ModelID\n\t}\n\treturn strings.TrimSpace(next.ModelID) != strings.TrimSpace(previous)\n}\n\n// PatchKnowledgeBaseRequest changes the settings it carries. A field left\n// out stays as it is, including fields inside chunking, indexing and models.\ntype PatchKnowledgeBaseRequest struct {\n\t// New name. Omit to keep the current one.\n\tName *string `json:\"name\" extensions:\"x-agent\"`\n\t// New description. Omit to keep it; an empty string clears it.\n\tDescription *string `json:\"description\" extensions:\"x-agent\"`\n\t// Embedding model. Cannot change after the knowledge base has documents.\n\tEmbeddingModelID *string `json:\"embedding_model_id\" extensions:\"x-agent=embedding_model_id\"`\n\t// Summary model. model.list returns the ids.\n\tSummaryModelID *string `json:\"summary_model_id\" extensions:\"x-agent=summary_model_id\"`\n\t// Storage instance to bind. Omit to keep the current one.\n\tStorageBackendID *string `json:\"storage_backend_id\" extensions:\"x-agent=storage_backend_id\"`\n\t// File extensions whose parser routing should change, e.g. [\"pdf\", \"docx\"]. Other file types keep their rules.\n\tParserFileTypes []string `json:\"parser_file_types,omitempty\" extensions:\"x-agent,x-agent-maximum=20\"`\n\t// Engine name from knowledge_base.list_parser_engines; empty removes explicit routing for parser_file_types.\n\tParserEngine *string `json:\"parser_engine,omitempty\" extensions:\"x-agent\"`\n\t// Treat the first XLSX row as headers. Requires parser_file_types including xlsx and an explicit parser_engine.\n\tParserXLSXFirstRowAsHeader *bool `json:\"parser_xlsx_first_row_as_header,omitempty\" extensions:\"x-agent\"`\n\t// Run image captions in the default image pipeline. Set image_pipeline=default to select that pipeline.\n\tImageCaptionEnabled *bool `json:\"image_caption_enabled,omitempty\" extensions:\"x-agent\"`\n\t// Run OCR in the default image pipeline. At least one of captions or OCR must stay enabled.\n\tImageOCREnabled *bool `json:\"image_ocr_enabled,omitempty\" extensions:\"x-agent\"`\n\t// Chunking settings. Only the fields present are changed.\n\tChunking *types.ChunkingConfig `json:\"chunking_config\"`\n\t// Indexing pipelines. A flag left out stays as it is.\n\tIndexing *types.IndexingStrategy `json:\"indexing_strategy\"`\n\t// Image description settings.\n\tImage *types.ImageProcessingConfig `json:\"image_processing_config\"`\n\t// FAQ indexing. Only for an FAQ knowledge base.\n\tFAQ *types.FAQConfig `json:\"faq_config\"`\n\t// Wiki page settings.\n\tWiki *types.WikiConfig `json:\"wiki_config\"`\n\t// Automatic tagging.\n\tAutoTag *types.AutoTagConfig `json:\"auto_tag_config\"`\n\t// AI description of the knowledge base.\n\tProfile *types.KnowledgeBaseProfileConfig `json:\"profile_config\"`\n\t// Image captions.\n\tVLM *types.VLMConfig `json:\"vlm_config\"`\n\t// Speech transcription.\n\tASR *types.ASRConfig `json:\"asr_config\"`\n\t// Graph extraction. Node types stay in the knowledge base editor.\n\tExtract *types.ExtractConfig `json:\"extract_config\"`\n\t// Generated questions for each chunk.\n\tQuestions *types.QuestionGenerationConfig `json:\"question_generation_config\"`\n}\n\n// knowledgeBaseUpdate is the merged result of a partial knowledge base edit.\ntype knowledgeBaseUpdate struct {\n\tName        string\n\tDescription string\n\tConfig      *types.KnowledgeBaseConfig\n\tVLM         *types.VLMConfig\n}\n\n// applyKnowledgeBasePatch overlays the JSON sections that are present onto\n// the stored knowledge base. Omitted flags and nested fields stay.\nfunc applyKnowledgeBasePatch(\n\tkb *types.KnowledgeBase, patch PatchKnowledgeBaseRequest, sections map[string]json.RawMessage,\n) (knowledgeBaseUpdate, error) {\n\tout := knowledgeBaseUpdate{Name: kb.Name, Description: kb.Description}\n\tif patch.Name != nil {\n\t\tout.Name = strings.TrimSpace(*patch.Name)\n\t\tif out.Name == \"\" {\n\t\t\treturn out, apperrors.NewBadRequestError(\"name cannot be empty\")\n\t\t}\n\t}\n\tif patch.Description != nil {\n\t\tout.Description = *patch.Description\n\t}\n\n\tcfg := &types.KnowledgeBaseConfig{ChunkingConfig: kb.ChunkingConfig}\n\tused := false\n\tmerge := func(key string, dest any) error {\n\t\traw, ok := sections[key]\n\t\tif !ok || len(raw) == 0 || string(raw) == \"null\" {\n\t\t\treturn nil\n\t\t}\n\t\tif err := json.Unmarshal(raw, dest); err != nil {\n\t\t\treturn apperrors.NewBadRequestError(\"invalid \" + key).WithDetails(err.Error())\n\t\t}\n\t\tused = true\n\t\treturn nil\n\t}\n\n\tchunking := kb.ChunkingConfig\n\tif err := merge(\"chunking_config\", &chunking); err != nil {\n\t\treturn out, err\n\t}\n\tif patch.ParserFileTypes != nil || patch.ParserEngine != nil || patch.ParserXLSXFirstRowAsHeader != nil {\n\t\tif err := applyParserRoutingPatch(&chunking, patch, sections); err != nil {\n\t\t\treturn out, err\n\t\t}\n\t\tused = true\n\t}\n\tcfg.ChunkingConfig = chunking\n\n\tstrategy := kb.IndexingStrategy\n\tbefore := len(sections[\"indexing_strategy\"])\n\tif err := merge(\"indexing_strategy\", &strategy); err != nil {\n\t\treturn out, err\n\t}\n\tif before > 0 && string(sections[\"indexing_strategy\"]) != \"null\" {\n\t\tcfg.IndexingStrategy = &strategy\n\t}\n\n\timage := kb.ImageProcessingConfig\n\timage.ImagePipelineParams = maps.Clone(image.ImagePipelineParams)\n\tif err := merge(\"image_processing_config\", &image); err != nil {\n\t\treturn out, err\n\t}\n\tif patch.ImageCaptionEnabled != nil || patch.ImageOCREnabled != nil {\n\t\tif types.ResolveImagePipelineID(&image) != types.ImagePipelineDefault {\n\t\t\treturn out, apperrors.NewBadRequestError(\n\t\t\t\t\"image_caption_enabled and image_ocr_enabled require image_pipeline=default\",\n\t\t\t)\n\t\t}\n\t\tif image.ImagePipelineParams == nil {\n\t\t\timage.ImagePipelineParams = map[string]any{}\n\t\t}\n\t\t// The switch is stored under the slot of the pipeline that declares it,\n\t\t// and nowhere else: a second spelling would be a setting with two homes,\n\t\t// and the run reads only the slot. The keys come from the pipeline's own\n\t\t// declaration rather than being spelled here, so a rename cannot leave\n\t\t// this call site writing something nothing reads.\n\t\tfor key, value := range map[string]*bool{\n\t\t\tservice.ImageCaptionSwitchKey: patch.ImageCaptionEnabled,\n\t\t\tservice.ImageOCRSwitchKey:     patch.ImageOCREnabled,\n\t\t} {\n\t\t\tif value != nil {\n\t\t\t\timage.ImagePipelineParams[types.SlotKey(string(types.ImagePipelineDefault), key)] = *value\n\t\t\t}\n\t\t}\n\t\tused = true\n\t}\n\tif (len(\n\t\tsections[\"image_processing_config\"],\n\t) > 0 && string(\n\t\tsections[\"image_processing_config\"],\n\t) != \"null\") || patch.ImageCaptionEnabled != nil || patch.ImageOCREnabled != nil {\n\t\tcfg.ImageProcessingConfig = &image\n\t}\n\n\tfaq := types.FAQConfig{}\n\tif kb.FAQConfig != nil {\n\t\tfaq = *kb.FAQConfig\n\t}\n\tif err := merge(\"faq_config\", &faq); err != nil {\n\t\treturn out, err\n\t}\n\tif _, ok := sections[\"faq_config\"]; ok && string(sections[\"faq_config\"]) != \"null\" {\n\t\tcfg.FAQConfig = &faq\n\t}\n\n\twiki := types.WikiConfig{}\n\tif kb.WikiConfig != nil {\n\t\twiki = *kb.WikiConfig\n\t}\n\tif err := merge(\"wiki_config\", &wiki); err != nil {\n\t\treturn out, err\n\t}\n\tif _, ok := sections[\"wiki_config\"]; ok && string(sections[\"wiki_config\"]) != \"null\" {\n\t\tcfg.WikiConfig = &wiki\n\t}\n\n\tautoTag := types.AutoTagConfig{}\n\tif kb.AutoTagConfig != nil {\n\t\tautoTag = *kb.AutoTagConfig\n\t}\n\tif err := merge(\"auto_tag_config\", &autoTag); err != nil {\n\t\treturn out, err\n\t}\n\tif _, ok := sections[\"auto_tag_config\"]; ok && string(sections[\"auto_tag_config\"]) != \"null\" {\n\t\tcfg.AutoTagConfig = &autoTag\n\t}\n\n\tprofile := types.KnowledgeBaseProfileConfig{}\n\tif kb.ProfileConfig != nil {\n\t\tprofile = *kb.ProfileConfig\n\t}\n\tif err := merge(\"profile_config\", &profile); err != nil {\n\t\treturn out, err\n\t}\n\tif _, ok := sections[\"profile_config\"]; ok && string(sections[\"profile_config\"]) != \"null\" {\n\t\tcfg.ProfileConfig = &profile\n\t}\n\n\tasr := kb.ASRConfig\n\tif err := merge(\"asr_config\", &asr); err != nil {\n\t\treturn out, err\n\t}\n\tif _, ok := sections[\"asr_config\"]; ok && string(sections[\"asr_config\"]) != \"null\" {\n\t\tcfg.ASRConfig = &asr\n\t}\n\n\textract := types.ExtractConfig{}\n\tif kb.ExtractConfig != nil {\n\t\textract = *kb.ExtractConfig\n\t}\n\tif err := merge(\"extract_config\", &extract); err != nil {\n\t\treturn out, err\n\t}\n\tif _, ok := sections[\"extract_config\"]; ok && string(sections[\"extract_config\"]) != \"null\" {\n\t\tif err := validateExtractConfig(&extract); err != nil {\n\t\t\treturn out, err\n\t\t}\n\t\tcfg.ExtractConfig = &extract\n\t}\n\n\tquestions := types.QuestionGenerationConfig{}\n\tif kb.QuestionGenerationConfig != nil {\n\t\tquestions = *kb.QuestionGenerationConfig\n\t}\n\tif err := merge(\"question_generation_config\", &questions); err != nil {\n\t\treturn out, err\n\t}\n\tif _, ok := sections[\"question_generation_config\"]; ok && string(sections[\"question_generation_config\"]) != \"null\" {\n\t\tcfg.QuestionGenerationConfig = &questions\n\t}\n\n\tvlm := kb.VLMConfig\n\tif err := merge(\"vlm_config\", &vlm); err != nil {\n\t\treturn out, err\n\t}\n\tif _, ok := sections[\"vlm_config\"]; ok && string(sections[\"vlm_config\"]) != \"null\" {\n\t\tout.VLM = &vlm\n\t}\n\n\tif patch.EmbeddingModelID != nil {\n\t\tcfg.EmbeddingModelID = patch.EmbeddingModelID\n\t\tused = true\n\t}\n\tif patch.SummaryModelID != nil {\n\t\tcfg.SummaryModelID = patch.SummaryModelID\n\t\tused = true\n\t}\n\tif patch.StorageBackendID != nil {\n\t\tcfg.StorageBackendID = patch.StorageBackendID\n\t\tused = true\n\t}\n\tif used {\n\t\tout.Config = cfg\n\t}\n\treturn out, nil\n}\n\n// fillOmittedIndexingFlags keeps DefaultIndexingStrategy for flags the\n// create body did not mention.\nfunc fillOmittedIndexingFlags(raw []byte, kb *types.KnowledgeBase) {\n\tvar body map[string]json.RawMessage\n\tif err := json.Unmarshal(raw, &body); err != nil {\n\t\treturn\n\t}\n\tstrategyRaw, ok := body[\"indexing_strategy\"]\n\tif !ok || len(strategyRaw) == 0 || string(strategyRaw) == \"null\" {\n\t\treturn\n\t}\n\tvar present map[string]json.RawMessage\n\tif err := json.Unmarshal(strategyRaw, &present); err != nil {\n\t\treturn\n\t}\n\tdefaults := types.DefaultIndexingStrategy()\n\tif _, ok := present[\"vector_enabled\"]; !ok {\n\t\tkb.IndexingStrategy.VectorEnabled = defaults.VectorEnabled\n\t}\n\tif _, ok := present[\"keyword_enabled\"]; !ok {\n\t\tkb.IndexingStrategy.KeywordEnabled = defaults.KeywordEnabled\n\t}\n\tif _, ok := present[\"wiki_enabled\"]; !ok {\n\t\tkb.IndexingStrategy.WikiEnabled = defaults.WikiEnabled\n\t}\n\tif _, ok := present[\"graph_enabled\"]; !ok {\n\t\tkb.IndexingStrategy.GraphEnabled = defaults.GraphEnabled\n\t}\n}\n\n// PatchKnowledgeBase godoc\n// @Summary      部分更新知识库\n// @Description  修改请求里出现的设置。未出现的字段保持不变，包括分块、索引和模型里没写到的项。\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        id       path      string                            true  \"知识库ID\"  extensions(x-agent=knowledge_base_id)\n// @Param        request  body      handler.PatchKnowledgeBaseRequest true  \"要修改的字段\"\n// @Success      200      {object}  handler.DataResponse{data=handler.KnowledgeBaseView}  \"更新后的知识库\"\n// @Failure      400      {object}  errors.AppError                                      \"请求参数错误\"\n// @Failure      403      {object}  errors.AppError                                      \"无权限\"\n// @Failure      404      {object}  errors.AppError                                      \"知识库不存在\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @x-agent      {\"id\":\"knowledge_base.update\",\"risk\":\"write\",\"target\":\"knowledge_base.get\",\"label\":\"name\"}\n// @x-agent-hint \"Changes the settings you send; a field left out is kept, including one indexing flag or one chunking field. Model ids come from model.list. embedding_model_id cannot change after documents exist. vector_store_id cannot be changed. Parsing settings (strategy, enable_parent_child, parent_chunk_size, child_chunk_size, VLM/ASR and question_generation_enabled/question_count) affect future parses; existing documents need an explicit knowledge.reparse or knowledge.batch_reparse. Read current settings first. For parser routing send parser_file_types and parser_engine from knowledge_base.list_parser_engines; empty parser_engine restores defaults. Use image_pipeline=smartocr for adaptive OCR, or default plus image_caption_enabled/image_ocr_enabled for manual image processing. Graph node types stay in the knowledge base editor.\"\n// @Router       /knowledge-bases/{id} [patch]\nfunc (h *KnowledgeBaseHandler) PatchKnowledgeBase(c *gin.Context) {\n\tctx := c.Request.Context()\n\tcurrentKB, id, _, permission, err := h.validateAndGetKnowledgeBase(c)\n\tif err != nil {\n\t\t_ = c.Error(err)\n\t\treturn\n\t}\n\tif permission != types.OrgRoleAdmin && permission != types.OrgRoleEditor {\n\t\t_ = c.Error(apperrors.NewForbiddenError(\"No permission to update knowledge base\"))\n\t\treturn\n\t}\n\tlimitJSONBody(c, knowledgeBaseJSONMaxBytes)\n\tbody, err := io.ReadAll(c.Request.Body)\n\tif err != nil {\n\t\tif isRequestBodyTooLarge(err) {\n\t\t\t_ = c.Error(apperrors.NewBadRequestError(\"request body is too large\"))\n\t\t\treturn\n\t\t}\n\t\t_ = c.Error(apperrors.NewBadRequestError(\"Invalid request parameters\").WithDetails(err.Error()))\n\t\treturn\n\t}\n\tvar patch PatchKnowledgeBaseRequest\n\tif err := json.Unmarshal(body, &patch); err != nil {\n\t\tlogger.Error(ctx, \"Failed to parse request parameters\", err)\n\t\t_ = c.Error(apperrors.NewBadRequestError(\"Invalid request parameters\").WithDetails(err.Error()))\n\t\treturn\n\t}\n\tvar sections map[string]json.RawMessage\n\tif err := json.Unmarshal(body, &sections); err != nil {\n\t\t_ = c.Error(apperrors.NewBadRequestError(\"Invalid request parameters\").WithDetails(err.Error()))\n\t\treturn\n\t}\n\tupdate, err := applyKnowledgeBasePatch(currentKB, patch, sections)\n\tif err != nil {\n\t\t_ = c.Error(err)\n\t\treturn\n\t}\n\tif err := validateKnowledgeBaseSettingsUpdate(c, currentKB, update.Config, update.VLM); err != nil {\n\t\t_ = c.Error(err)\n\t\treturn\n\t}\n\tif update.Config != nil || update.VLM != nil {\n\t\tprobe := &types.KnowledgeBase{ChunkingConfig: currentKB.ChunkingConfig, VLMConfig: currentKB.VLMConfig}\n\t\tif update.Config != nil {\n\t\t\tprobe.ChunkingConfig = update.Config.ChunkingConfig\n\t\t\tprobe.WikiConfig = update.Config.WikiConfig\n\t\t\tprobe.ProfileConfig = update.Config.ProfileConfig\n\t\t\tif update.Config.ImageProcessingConfig != nil {\n\t\t\t\tprobe.ImageProcessingConfig = *update.Config.ImageProcessingConfig\n\t\t\t}\n\t\t}\n\t\tif update.VLM != nil {\n\t\t\tprobe.VLMConfig = *update.VLM\n\t\t}\n\t\tif err := validateKnowledgeBasePromptInstructions(probe); err != nil {\n\t\t\t_ = c.Error(err)\n\t\t\treturn\n\t\t}\n\t}\n\tkb, err := h.service.UpdateKnowledgeBase(ctx, id, update.Name, update.Description, update.Config, update.VLM)\n\tif err != nil {\n\t\tif appErr, ok := apperrors.IsAppError(err); ok {\n\t\t\t_ = c.Error(appErr)\n\t\t\treturn\n\t\t}\n\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\t_ = c.Error(apperrors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\tcallerTenantID := c.GetUint64(types.TenantIDContextKey.String())\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"data\":    buildKBResponse(kb, h.resolveKBStoreView(ctx, kb, callerTenantID), nil),\n\t})\n}\n\n// GenerateKnowledgeBaseProfile godoc\n// @Summary      生成知识库描述\n// @Description  基于文档画像聚合，立即重新生成知识库的 AI 描述（不覆盖手写描述）\n// @Tags         知识库\n// @Produce      json\n// @Param        id   path      string  true  \"知识库ID\"  extensions(x-agent=knowledge_base_id)\n// @Success      200  {object}  handler.DataResponse{data=types.KnowledgeBaseProfile}  \"生成的知识库画像\"\n// @Failure      400  {object}  errors.AppError                                       \"知识库类型不支持或未配置模型\"\n// @Failure      403  {object}  errors.AppError                                       \"无权限\"\n// @Failure      404  {object}  errors.AppError                                       \"知识库不存在\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @x-agent      {\"id\":\"knowledge_base.generate_profile\",\"risk\":\"write\",\"target\":\"knowledge_base.get\",\"label\":\"name\"}\n// @x-agent-hint \"Regenerates the AI summary of what the knowledge base covers, with one model call. A description the user wrote is kept.\"\n// @Router       /knowledge-bases/{id}/profile/generate [post]\nfunc (h *KnowledgeBaseHandler) GenerateKnowledgeBaseProfile(c *gin.Context) {\n\tctx := c.Request.Context()\n\tkb, id, _, permission, err := h.validateAndGetKnowledgeBase(c)\n\tif err != nil {\n\t\t_ = c.Error(err)\n\t\treturn\n\t}\n\tif permission != types.OrgRoleAdmin && permission != types.OrgRoleEditor {\n\t\t_ = c.Error(apperrors.NewForbiddenError(\"No permission to update knowledge base\"))\n\t\treturn\n\t}\n\tif h.profileService == nil {\n\t\t_ = c.Error(apperrors.NewInternalServerError(\"knowledge base profile service unavailable\"))\n\t\treturn\n\t}\n\tgenCtx, cancel := context.WithTimeout(ctx, knowledgeBaseProfileRequestTimeout)\n\tdefer cancel()\n\tprofile, err := h.profileService.GenerateKnowledgeBaseProfile(genCtx, kb, true)\n\tif err != nil {\n\t\tlogger.ErrorWithFields(ctx, err, map[string]interface{}{\"knowledge_base_id\": id})\n\t\tswitch {\n\t\tcase stderrors.Is(err, types.ErrKnowledgeBaseProfileUnsupported),\n\t\t\tstderrors.Is(err, types.ErrKnowledgeBaseProfileModelNotConfigured):\n\t\t\t_ = c.Error(apperrors.NewBadRequestError(err.Error()))\n\t\tdefault:\n\t\t\t_ = c.Error(apperrors.NewInternalServerError(err.Error()))\n\t\t}\n\t\treturn\n\t}\n\tc.JSON(http.StatusOK, gin.H{\"success\": true, \"data\": profile})\n}\n\n// knowledgeBaseProfileRequestTimeout bounds the synchronous regeneration a\n// user triggers from the settings dialog: one aggregation plus one small\n// model call.\nconst knowledgeBaseProfileRequestTimeout = 2 * time.Minute\n\n// DeleteKnowledgeBase godoc\n// @Summary      删除知识库\n// @Description  删除指定的知识库及其所有内容\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        id   path      string  true  \"知识库ID\"  extensions(x-agent=knowledge_base_id)\n// @Success      200  {object}  handler.MessageResponse  \"删除成功\"\n// @Failure      400  {object}  errors.AppError          \"请求参数错误\"\n// @Failure      403  {object}  errors.AppError          \"仅所有者可删除\"\n// @Failure      404  {object}  errors.AppError          \"知识库不存在\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @x-agent      {\"id\":\"knowledge_base.delete\",\"risk\":\"destructive\",\"target\":\"knowledge_base.get\",\"label\":\"name\"}\n// @x-agent-hint \"Deletes the knowledge base and every document in it. Cannot be undone. Only the owner can delete it.\"\n// @Router       /knowledge-bases/{id} [delete]\nfunc (h *KnowledgeBaseHandler) DeleteKnowledgeBase(c *gin.Context) {\n\tctx := c.Request.Context()\n\tlogger.Info(ctx, \"Start deleting knowledge base\")\n\n\t// Validate and get the knowledge base\n\tkb, id, _, permission, err := h.validateAndGetKnowledgeBase(c)\n\tif err != nil {\n\t\tc.Error(err)\n\t\treturn\n\t}\n\n\t// Only owner (admin with matching tenant) can delete knowledge base\n\ttenantID, _ := c.Get(types.TenantIDContextKey.String())\n\tif kb.TenantID != tenantID.(uint64) || permission != types.OrgRoleAdmin {\n\t\tc.Error(apperrors.NewForbiddenError(\"Only knowledge base owner can delete\"))\n\t\treturn\n\t}\n\n\tlogger.Infof(ctx, \"Deleting knowledge base, ID: %s, name: %s\",\n\t\tsecutils.SanitizeForLog(id), secutils.SanitizeForLog(kb.Name))\n\n\t// Delete the knowledge base\n\tif err := h.service.DeleteKnowledgeBase(ctx, id); err != nil {\n\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\tc.Error(apperrors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\n\tlogger.Infof(ctx, \"Knowledge base deleted successfully, ID: %s\",\n\t\tsecutils.SanitizeForLog(id))\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"message\": \"Knowledge base deleted successfully\",\n\t})\n}\n\ntype CopyKnowledgeBaseRequest struct {\n\tTaskID string `json:\"task_id\"`\n\t// Source knowledge base ID; the assistant always copies to a new knowledge base.\n\tSourceID string `json:\"source_id\" binding:\"required\" extensions:\"x-agent=knowledge_base_id\"`\n\tTargetID string `json:\"target_id\"`\n}\n\n// CopyKnowledgeBaseResponse defines the response for copy knowledge base\ntype CopyKnowledgeBaseResponse struct {\n\tTaskID   string `json:\"task_id\" extensions:\"x-agent\"`\n\tSourceID string `json:\"source_id\" extensions:\"x-agent=source_knowledge_base_id\"`\n\tTargetID string `json:\"target_id\" extensions:\"x-agent=knowledge_base_id\"`\n\tMessage  string `json:\"message\" extensions:\"x-agent\"`\n}\n\ntype DuplicateKnowledgeBaseResponse struct {\n\tSourceID      string      `json:\"source_id\"`\n\tTargetID      string      `json:\"target_id\"`\n\tMessage       string      `json:\"message\"`\n\tKnowledgeBase interface{} `json:\"knowledge_base\"`\n}\n\n// CopyKnowledgeBase godoc\n// @Summary      复制知识库\n// @Description  将一个知识库的内容复制到另一个知识库（异步任务）\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        request  body      CopyKnowledgeBaseRequest   true  \"复制请求\"\n// @Success      200      {object}  handler.DataResponse{data=handler.CopyKnowledgeBaseResponse}  \"任务ID\"\n// @Failure      400      {object}  errors.AppError                                              \"请求参数错误\"\n// @Failure      401      {object}  errors.AppError                                              \"未认证\"\n// @Failure      403      {object}  errors.AppError                                              \"无权限\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @x-agent {\"id\":\"knowledge_base.copy\",\"risk\":\"write\",\"target\":\"knowledge_base.get\",\"label\":\"name\"}\n// @x-agent-hint \"Copy content into a NEW knowledge base in the same workspace. Starts a background job; follow knowledge_base.get_copy_progress until completed before claiming success. Existing destination replacement is not supported.\"\n// @Router       /knowledge-bases/copy [post]\nfunc (h *KnowledgeBaseHandler) CopyKnowledgeBase(c *gin.Context) {\n\tctx := c.Request.Context()\n\tvar req CopyKnowledgeBaseRequest\n\tif err := c.ShouldBindJSON(&req); err != nil {\n\t\tlogger.Error(ctx, \"Failed to parse request parameters\", err)\n\t\tc.Error(apperrors.NewBadRequestError(\"Invalid request parameters\").WithDetails(err.Error()))\n\t\treturn\n\t}\n\n\tcaller := types.CallerFromContext(ctx)\n\tif caller.TenantID == 0 {\n\t\t_ = c.Error(errors.NewUnauthorizedError(\"Unauthorized\"))\n\t\treturn\n\t}\n\ttenantID := caller.TenantID\n\tsourceGrant, err := resolveHandlerKBAccessFor(c, req.SourceID, h.service, nil, nil, types.OrgRoleViewer)\n\tif err != nil {\n\t\tc.Error(err)\n\t\treturn\n\t}\n\tsourceKB := sourceGrant.KnowledgeBase\n\tif sourceKB.TenantID != caller.TenantID {\n\t\t_ = c.Error(errors.NewForbiddenError(\"No permission to copy this knowledge base\"))\n\t\treturn\n\t}\n\ttaskID := req.TaskID\n\tif taskID == \"\" {\n\t\ttaskID = utils.GenerateTaskID(\"kb_clone\", caller.TenantID, req.SourceID)\n\t} else if err := requireTaskProgressTenant(ctx, taskID); err != nil {\n\t\t_ = c.Error(err)\n\t\treturn\n\t}\n\tcreate := req.TargetID == \"\"\n\ttargetKB := &types.KnowledgeBase{ID: uuid.NewString(), TenantID: caller.TenantID}\n\tif create {\n\t\tif !types.IsSyntheticUserID(caller.UserID) {\n\t\t\ttargetKB.CreatorID = caller.UserID\n\t\t}\n\t} else {\n\t\ttargetGrant, err := resolveHandlerKBAccessFor(c, req.TargetID, h.service, nil, nil, types.OrgRoleEditor)\n\t\tif err != nil {\n\t\t\t_ = c.Error(err)\n\t\t\treturn\n\t\t}\n\t\ttargetKB = targetGrant.KnowledgeBase\n\t\tif targetKB.TenantID != caller.TenantID {\n\t\t\tc.Error(errors.NewForbiddenError(\"No permission to copy to this knowledge base\"))\n\t\t\treturn\n\t\t}\n\t\tif err := middleware.EvaluateOwnershipOrRole(c.Request.Context(),\n\t\t\th.cfg,\n\t\t\ttypes.TenantRoleAdmin,\n\t\t\tfunc() (string,\n\t\t\t\terror,\n\t\t\t) {\n\t\t\t\treturn targetKB.CreatorID,\n\t\t\t\t\tnil\n\t\t\t}); err != nil {\n\t\t\t_ = c.Error(errors.NewForbiddenError(\"No permission to replace this knowledge base's contents\"))\n\t\t\treturn\n\t\t}\n\t\ttenant, _ := ctx.Value(types.TenantInfoContextKey).(*types.Tenant)\n\t\tif err := access.ValidateKBTransferCompatibility(sourceKB,\n\t\t\ttargetKB,\n\t\t\taccess.KBTransferClone,\n\t\t\t\"\",\n\t\t\ttenant); err != nil {\n\t\t\t_ = c.Error(errors.NewBadRequestError(err.Error()))\n\t\t\treturn\n\t\t}\n\t}\n\tctx, err = access.WithKBTransfer(c.Request.Context(), sourceKB, targetKB, access.KBTransferClone, taskID, create)\n\tif err != nil {\n\t\t_ = c.Error(kbAccessHTTPError(err))\n\t\treturn\n\t}\n\t// Reserve the destination in the payload; enqueue failures do not leave\n\t// empty KBs and every worker delivery creates/resumes the same destination.\n\treq.TargetID = targetKB.ID\n\n\t// Create KB clone payload\n\tpayload := types.KBClonePayload{\n\t\tTenantID:     tenantID,\n\t\tTaskID:       taskID,\n\t\tSourceID:     req.SourceID,\n\t\tTargetID:     req.TargetID,\n\t\tCreateTarget: create,\n\t\tCreatorID:    targetKB.CreatorID,\n\t\tInitiator:    types.TaskInitiatorFromContext(ctx),\n\t}\n\tlangfuse.InjectTracing(ctx, &payload)\n\n\tpayloadBytes, err := json.Marshal(payload)\n\tif err != nil {\n\t\tlogger.Errorf(ctx, \"Failed to marshal KB clone payload: %v\", err)\n\t\tc.Error(apperrors.NewInternalServerError(\"Failed to create task\"))\n\t\treturn\n\t}\n\n\t// Enqueue KB clone task to Asynq\n\ttask := asynq.NewTask(types.TypeKBClone, payloadBytes,\n\t\tasynq.TaskID(taskID), asynq.Queue(types.QueueMaintenance),\n\t\tasynq.MaxRetry(3), asynq.Timeout(2*time.Hour))\n\tinfo, err := h.asynqClient.Enqueue(task)\n\tif err != nil {\n\t\tlogger.Errorf(ctx, \"Failed to enqueue KB clone task: %v\", err)\n\t\tc.Error(apperrors.NewInternalServerError(\"Failed to enqueue task\"))\n\t\treturn\n\t}\n\n\tlogger.Infof(ctx, \"KB clone task enqueued: %s, asynq task ID: %s, source: %s, target: %s\",\n\t\ttaskID, info.ID, secutils.SanitizeForLog(req.SourceID), secutils.SanitizeForLog(req.TargetID))\n\n\t// Save initial progress to Redis so frontend can query immediately\n\tinitialProgress := &types.KBCloneProgress{\n\t\tTaskID:    taskID,\n\t\tSourceID:  req.SourceID,\n\t\tTargetID:  req.TargetID,\n\t\tStatus:    types.KBCloneStatusPending,\n\t\tProgress:  0,\n\t\tMessage:   \"Task queued, waiting to start...\",\n\t\tCreatedAt: time.Now().Unix(),\n\t\tUpdatedAt: time.Now().Unix(),\n\t}\n\tif err := h.knowledgeService.SaveKBCloneProgress(ctx, initialProgress); err != nil {\n\t\tlogger.Warnf(ctx, \"Failed to save initial KB clone progress: %v\", err)\n\t\t// Don't fail the request, task is already enqueued\n\t}\n\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"data\": CopyKnowledgeBaseResponse{\n\t\t\tTaskID:   taskID,\n\t\t\tSourceID: req.SourceID,\n\t\t\tTargetID: req.TargetID,\n\t\t\tMessage:  \"Knowledge base copy task started\",\n\t\t},\n\t})\n}\n\n// DuplicateKnowledgeBase godoc\n// @Summary      创建知识库副本\n// @Description  创建一个只包含设置的新知识库副本，不复制知识、FAQ 内容、分块、索引、Wiki 页面、分享或置顶状态\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        id       path      string                  true  \"源知识库 ID\" extensions(x-agent=knowledge_base_id)\n// @Success      201      {object}  handler.DataResponse{data=handler.DuplicateKnowledgeBaseData}  \"创建后的知识库副本\"\n// @Failure      400      {object}  errors.AppError                                               \"请求参数错误\"\n// @Failure      403      {object}  errors.AppError                                               \"无权限\"\n// @Failure      404      {object}  errors.AppError                                               \"知识库不存在\"\n// @Security     Bearer\n// @x-agent {\"id\":\"knowledge_base.duplicate\",\"risk\":\"write\",\"target\":\"knowledge_base.get\",\"label\":\"name\"}\n// @x-agent-hint \"Create an empty knowledge base with the source settings only. Does NOT copy documents, FAQ, chunks, indexes, wiki, sharing or pins. To copy content use knowledge_base.copy instead. Rename the new knowledge_base_id with knowledge_base.update if needed.\"\n// @Router       /knowledge-bases/{id}/duplicate [post]\nfunc (h *KnowledgeBaseHandler) DuplicateKnowledgeBase(c *gin.Context) {\n\tctx := c.Request.Context()\n\tsourceID := c.Param(\"id\")\n\tif sourceID == \"\" {\n\t\tc.Error(apperrors.NewBadRequestError(\"Knowledge base ID cannot be empty\"))\n\t\treturn\n\t}\n\n\tcallerTenantID := c.GetUint64(types.TenantIDContextKey.String())\n\tsourceKB, err := h.service.GetKnowledgeBaseByID(ctx, sourceID)\n\tif err != nil {\n\t\tif stderrors.Is(err, repository.ErrKnowledgeBaseNotFound) {\n\t\t\tc.Error(errors.NewNotFoundError(\"Source knowledge base not found\"))\n\t\t\treturn\n\t\t}\n\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\tc.Error(errors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\tif sourceKB.TenantID != callerTenantID {\n\t\tlogger.Warnf(ctx,\n\t\t\t\"Knowledge base duplicate rejected: source belongs to another tenant, source_id: %s, caller_tenant: %d, kb_tenant: %d\",\n\t\t\tsecutils.SanitizeForLog(sourceID), callerTenantID, sourceKB.TenantID)\n\t\tc.Error(errors.NewForbiddenError(\"No permission to duplicate this knowledge base\"))\n\t\treturn\n\t}\n\n\ttargetKB, err := h.service.DuplicateKnowledgeBase(ctx, sourceID)\n\tif err != nil {\n\t\tif appErr, ok := apperrors.IsAppError(err); ok {\n\t\t\tc.Error(appErr)\n\t\t\treturn\n\t\t}\n\t\tif stderrors.Is(err, repository.ErrKnowledgeBaseNotFound) {\n\t\t\tc.Error(errors.NewNotFoundError(\"Source knowledge base not found\"))\n\t\t\treturn\n\t\t}\n\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\tc.Error(errors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\n\tlogger.Infof(ctx, \"Knowledge base duplicate created, source: %s, target: %s\",\n\t\tsecutils.SanitizeForLog(sourceID), secutils.SanitizeForLog(targetKB.ID))\n\tc.JSON(http.StatusCreated, gin.H{\n\t\t\"success\": true,\n\t\t\"data\": DuplicateKnowledgeBaseResponse{\n\t\t\tSourceID:      sourceID,\n\t\t\tTargetID:      targetKB.ID,\n\t\t\tMessage:       \"Knowledge base duplicate created\",\n\t\t\tKnowledgeBase: buildKBResponse(targetKB, h.resolveKBStoreView(ctx, targetKB, callerTenantID), nil),\n\t\t},\n\t})\n}\n\n// GetKBCloneProgress godoc\n// @Summary      获取知识库复制进度\n// @Description  获取知识库复制任务的进度\n// @Tags         知识库\n// @Accept       json\n// @Produce      json\n// @Param        task_id  path      string  true  \"任务ID\" extensions(x-agent)\n// @Success      200      {object}  handler.DataResponse{data=types.KBCloneProgress}  \"进度信息\"\n// @Failure      400      {object}  errors.AppError                                  \"请求参数错误\"\n// @Failure      404      {object}  errors.AppError                                  \"任务不存在\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @x-agent {\"id\":\"knowledge_base.get_copy_progress\",\"risk\":\"read\"}\n// @x-agent-hint \"Read a task_id from knowledge_base.copy; distinguish queued/running work from a completed or failed copy.\"\n// @Router       /knowledge-bases/copy/progress/{task_id} [get]\nfunc (h *KnowledgeBaseHandler) GetKBCloneProgress(c *gin.Context) {\n\tctx := c.Request.Context()\n\n\ttaskID := c.Param(\"task_id\")\n\tif taskID == \"\" {\n\t\tlogger.Error(ctx, \"Task ID is empty\")\n\t\tc.Error(apperrors.NewBadRequestError(\"Task ID cannot be empty\"))\n\t\treturn\n\t}\n\tif err := requireTaskProgressTenant(ctx, taskID); err != nil {\n\t\tc.Error(err)\n\t\treturn\n\t}\n\n\tprogress, err := h.knowledgeService.GetKBCloneProgress(ctx, taskID)\n\tif err != nil {\n\t\tlogger.ErrorWithFields(ctx, err, nil)\n\t\tc.Error(err)\n\t\treturn\n\t}\n\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"data\":    progress,\n\t})\n}\n\n// validateExtractConfig validates the graph configuration parameters\nfunc validateExtractConfig(config *types.ExtractConfig) error {\n\tif config == nil {\n\t\treturn nil\n\t}\n\tif !config.Enabled {\n\t\tconfig.Enabled = false\n\t\treturn nil\n\t}\n\t// Validate text field\n\tif config.Text == \"\" {\n\t\treturn apperrors.NewBadRequestError(\"text cannot be empty\")\n\t}\n\n\t// Validate tags field\n\tif len(config.Tags) == 0 {\n\t\treturn apperrors.NewBadRequestError(\"tags cannot be empty\")\n\t}\n\tfor i, tag := range config.Tags {\n\t\tif tag == \"\" {\n\t\t\treturn apperrors.NewBadRequestError(\"tag cannot be empty at index \" + strconv.Itoa(i))\n\t\t}\n\t}\n\n\t// Validate nodes\n\tif len(config.Nodes) == 0 {\n\t\treturn apperrors.NewBadRequestError(\"nodes cannot be empty\")\n\t}\n\tnodeNames := make(map[string]bool)\n\tfor i, node := range config.Nodes {\n\t\tif node.Name == \"\" {\n\t\t\treturn apperrors.NewBadRequestError(\"node name cannot be empty at index \" + strconv.Itoa(i))\n\t\t}\n\t\t// Check for duplicate node names\n\t\tif nodeNames[node.Name] {\n\t\t\treturn apperrors.NewBadRequestError(\"duplicate node name: \" + node.Name)\n\t\t}\n\t\tnodeNames[node.Name] = true\n\t}\n\n\tif len(config.Relations) == 0 {\n\t\treturn apperrors.NewBadRequestError(\"relations cannot be empty\")\n\t}\n\t// Validate relations\n\tfor i, relation := range config.Relations {\n\t\tif relation.Node1 == \"\" {\n\t\t\treturn apperrors.NewBadRequestError(\"relation node1 cannot be empty at index \" + strconv.Itoa(i))\n\t\t}\n\t\tif relation.Node2 == \"\" {\n\t\t\treturn apperrors.NewBadRequestError(\"relation node2 cannot be empty at index \" + strconv.Itoa(i))\n\t\t}\n\t\tif relation.Type == \"\" {\n\t\t\treturn apperrors.NewBadRequestError(\"relation type cannot be empty at index \" + strconv.Itoa(i))\n\t\t}\n\t\t// Check if referenced nodes exist\n\t\tif !nodeNames[relation.Node1] {\n\t\t\treturn apperrors.NewBadRequestError(\"relation references non-existent node1: \" + relation.Node1)\n\t\t}\n\t\tif !nodeNames[relation.Node2] {\n\t\t\treturn apperrors.NewBadRequestError(\"relation references non-existent node2: \" + relation.Node2)\n\t\t}\n\t}\n\n\treturn nil\n}\n\nfunc validateKnowledgeBasePromptInstructions(kb *types.KnowledgeBase) error {\n\tif err := types.ValidateKnowledgeBasePromptInstructions(kb); err != nil {\n\t\treturn apperrors.NewBadRequestError(err.Error())\n\t}\n\treturn nil\n}\n\n// ListMoveTargets returns knowledge bases eligible as move targets for the given source KB.\n// Filters: same Type, same EmbeddingModelID, different ID, not temporary.\n//\n// ListMoveTargets godoc\n// @Summary      获取可移动目标知识库列表\n// @Description  返回与源知识库 Type 一致、EmbeddingModelID 一致、非临时且不是自身的目标知识库列表\n// @Tags         知识库\n// @Produce      json\n// @Param        id   path      string                  true  \"源知识库 ID\"  extensions(x-agent=knowledge_base_id)\n// @Success      200  {object}  handler.DataResponse{data=[]types.KnowledgeBase}  \"可移动目标列表\"\n// @Failure      400  {object}  errors.AppError                                   \"请求参数错误\"\n// @Failure      401  {object}  errors.AppError                                   \"未认证\"\n// @Failure      403  {object}  errors.AppError                                   \"无权限\"\n// @Failure      404  {object}  errors.AppError                                   \"知识库不存在\"\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @x-agent      {\"id\":\"knowledge_base.list_move_targets\",\"risk\":\"read\"}\n// @x-agent-hint \"Knowledge bases the documents of this one can be moved to: same type and embedding model.\"\n// @Router       /knowledge-bases/{id}/move-targets [get]\nfunc (h *KnowledgeBaseHandler) ListMoveTargets(c *gin.Context) {\n\tctx := c.Request.Context()\n\n\tsourceKBID := c.Param(\"id\")\n\tif sourceKBID == \"\" {\n\t\tc.Error(apperrors.NewBadRequestError(\"Knowledge base ID is required\"))\n\t\treturn\n\t}\n\n\ttenantID, exists := c.Get(types.TenantIDContextKey.String())\n\tif !exists {\n\t\tc.Error(apperrors.NewUnauthorizedError(\"Unauthorized\"))\n\t\treturn\n\t}\n\n\t// Get source knowledge base\n\tsourceKB, err := h.service.GetKnowledgeBaseByID(ctx, sourceKBID)\n\tif err != nil {\n\t\tif stderrors.Is(err, repository.ErrKnowledgeBaseNotFound) {\n\t\t\tc.Error(errors.NewNotFoundError(\"Source knowledge base not found\"))\n\t\t\treturn\n\t\t}\n\t\tc.Error(errors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\tif sourceKB.TenantID != tenantID.(uint64) {\n\t\tc.Error(errors.NewForbiddenError(\"No permission to access this knowledge base\"))\n\t\treturn\n\t}\n\n\t// Get all knowledge bases\n\tallKBs, err := h.service.ListKnowledgeBases(ctx)\n\tif err != nil {\n\t\tc.Error(errors.NewInternalServerError(err.Error()))\n\t\treturn\n\t}\n\n\t// Filter eligible targets\n\ttargets := make([]*types.KnowledgeBase, 0)\n\tfor _, kb := range allKBs {\n\t\tif kb.ID == sourceKBID {\n\t\t\tcontinue\n\t\t}\n\t\tif kb.IsTemporary {\n\t\t\tcontinue\n\t\t}\n\t\tif kb.Type != sourceKB.Type {\n\t\t\tcontinue\n\t\t}\n\t\tif kb.EmbeddingModelID != sourceKB.EmbeddingModelID {\n\t\t\tcontinue\n\t\t}\n\t\ttargets = append(targets, kb)\n\t}\n\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"data\":    targets,\n\t})\n}\n\n// GetImageAttrsSchema godoc\n// @Summary      获取图片属性字典\n// @Description  返回当前版本的图片属性注册表、提示词版本和默认动作。全局只读，不绑定知识库。\n// @Tags         知识库\n// @Produce      json\n// @Success      200  {object}  handler.DataResponse{data=handler.ImageAttrSchemaData}\n// @Security     Bearer\n// @Security     ApiKeyAuth\n// @Router       /image-attrs/schema [get]\nfunc (h *KnowledgeBaseHandler) GetImageAttrsSchema(c *gin.Context) {\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"data\": gin.H{\n\t\t\t\"version\":         types.ImageAttrSchemaVersion,\n\t\t\t\"prompt\":          types.ImageAttrPromptVersion,\n\t\t\t\"attributes\":      types.ImageAttrRegistry,\n\t\t\t\"default_actions\": types.DefaultImageActions(),\n\t\t},\n\t})\n}\n\n// GetImagePipelines returns every registered image pipeline in the shape the\n// settings panel renders: id, name, and the fields each one owns. The panel\n// reads this instead of carrying a list of its own, so adding a pipeline is a\n// backend-only change — its fields arrive here already described, and no UI code\n// mentions the pipeline by name.\n//\n// The fields of two pipelines are deliberately allowed to share a key. Each is\n// private to the pipeline that declared it, which is why the knowledge base\n// stores them under that pipeline's own group rather than in one flat map.\n// Read-only, and global rather than per-KB, so only the Viewer role is required.\nfunc (h *KnowledgeBaseHandler) GetImagePipelines(c *gin.Context) {\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"data\":    service.ListImagePipelines(),\n\t})\n}\n\n// ValidateImagePipelines answers the settings panel's question — could what is\n// on screen be saved? — without saving anything. The panel asks as the user\n// types so the warnings arrive before the save rather than as a rejection after\n// it; the save path asks again on its own, so this endpoint is the polite half\n// of one check, not the whole of it.\n//\n// Nothing is judged here. The rules come from the pipeline being validated, the\n// same ones ListImagePipelines publishes, so a pipeline whose actions are not\n// the user's to switch off declares none and is never told that it is wrong.\n// Every broken rule is reported, each with the i18n key of its own wording and\n// the name of the field that is at fault: the panel translates and points, as\n// it does for the strings already on it.\nfunc (h *KnowledgeBaseHandler) ValidateImagePipelines(c *gin.Context) {\n\tvar request struct {\n\t\tPipelineID types.ImagePipelineID `json:\"pipeline_id\"`\n\t\tParams     map[string]any        `json:\"params\"`\n\t}\n\tif err := c.ShouldBindJSON(&request); err != nil {\n\t\tc.JSON(http.StatusBadRequest, gin.H{\n\t\t\t\"success\": false,\n\t\t\t\"message\": \"invalid request body\",\n\t\t})\n\t\treturn\n\t}\n\n\tbroken := service.BrokenImagePipelineRules(request.PipelineID, request.Params)\n\tif len(broken) == 0 {\n\t\tc.JSON(http.StatusOK, gin.H{\n\t\t\t\"success\": true,\n\t\t\t\"data\":    gin.H{\"valid\": true, \"violations\": []any{}},\n\t\t})\n\t\treturn\n\t}\n\n\tviolations := make([]gin.H, 0, len(broken))\n\tfor _, invalid := range broken {\n\t\tviolations = append(violations, gin.H{\n\t\t\t\"message_key\": invalid.MessageKey,\n\t\t\t\"field\":       invalid.Field,\n\t\t})\n\t}\n\tc.JSON(http.StatusOK, gin.H{\n\t\t\"success\": true,\n\t\t\"data\":    gin.H{\"valid\": false, \"violations\": violations},\n\t})\n}\n"
    },
    {
      "path": "internal/application/service/knowledgebase_search.go",
      "content": "package service\n\nimport (\n\t\"context\"\n\t\"fmt\"\n\n\t\"github.com/Tencent/WeKnora/internal/application/service/retriever\"\n\tapperrors \"github.com/Tencent/WeKnora/internal/errors\"\n\t\"github.com/Tencent/WeKnora/internal/logger\"\n\t\"github.com/Tencent/WeKnora/internal/models/embedding\"\n\t\"github.com/Tencent/WeKnora/internal/models/imageprep\"\n\t\"github.com/Tencent/WeKnora/internal/tracing/langfuse\"\n\t\"github.com/Tencent/WeKnora/internal/types\"\n\tsecutils \"github.com/Tencent/WeKnora/internal/utils\"\n)\n\n// maxRetrievalPoolSize bounds every retrieval depth derived from MatchCount:\n// the over-retrieval pool below and the doubling TopK of the FAQ iterative\n// path. Without it a caller-supplied MatchCount scales the vector-store query\n// depth without limit.\nconst maxRetrievalPoolSize = 500\n\n// GetQueryEmbedding computes the query embedding using the embedding model\n// associated with the given knowledge base. Callers can pre-compute and reuse\n// the result across multiple KBs that share the same embedding model and\n// configured vector dimension to avoid redundant embedding API calls.\nfunc (s *knowledgeBaseService) GetQueryEmbedding(ctx context.Context, kbID string, queryText string) ([]float32, error) {\n\tkb, err := s.repo.GetKnowledgeBaseByID(ctx, kbID)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\n\tcurrentTenantID := types.MustTenantIDFromContext(ctx)\n\tvar embeddingModel embedding.Embedder\n\n\tif kb.TenantID != currentTenantID {\n\t\tembeddingModel, err = s.modelService.GetEmbeddingModelForTenant(ctx, kb.EmbeddingModelID, kb.TenantID)\n\t} else {\n\t\tembeddingModel, err = s.modelService.GetEmbeddingModel(ctx, kb.EmbeddingModelID)\n\t}\n\tif err != nil {\n\t\tlogger.Errorf(ctx, \"GetQueryEmbedding: failed to get embedding model %s: %v\", kb.EmbeddingModelID, err)\n\t\treturn nil, err\n\t}\n\n\tvector, err := embeddingModel.Embed(types.WithEmbedQuery(ctx), queryText)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tif err := validateQueryEmbeddingDimension(embeddingModel, len(vector)); err != nil {\n\t\tlogger.Errorf(ctx, \"GetQueryEmbedding: %v\", err)\n\t\treturn nil, err\n\t}\n\treturn vector, nil\n}\n\n// GetQueryImageEmbedding computes the query embedding for an image using the\n// same multimodal model path the index used when it stored image_vector chunks,\n// so a query image is comparable with them. It returns an error when the KB's\n// embedding model has no image side: silently falling back to text recall would\n// answer a different question than the one asked.\nfunc (s *knowledgeBaseService) GetQueryImageEmbedding(\n\tctx context.Context, kbID string, img []byte,\n) ([]float32, error) {\n\tif len(img) == 0 {\n\t\treturn nil, fmt.Errorf(\"query image is empty\")\n\t}\n\tkb, err := s.repo.GetKnowledgeBaseByID(ctx, kbID)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tvar embeddingModel embedding.Embedder\n\tif kb.TenantID != types.MustTenantIDFromContext(ctx) {\n\t\tembeddingModel, err = s.modelService.GetEmbeddingModelForTenant(ctx, kb.EmbeddingModelID, kb.TenantID)\n\t} else {\n\t\tembeddingModel, err = s.modelService.GetEmbeddingModel(ctx, kb.EmbeddingModelID)\n\t}\n\tif err != nil {\n\t\tlogger.Errorf(ctx, \"GetQueryImageEmbedding: failed to get embedding model %s: %v\", kb.EmbeddingModelID, err)\n\t\treturn nil, err\n\t}\n\timageModel, ok := embedding.AsImageEmbedder(embeddingModel)\n\tif !ok {\n\t\t// A KB indexed without images has no image_vector rows to match; a\n\t\t// text query is the only recall it supports.\n\t\treturn nil, fmt.Errorf(\n\t\t\t\"embedding model %s cannot embed images; enable image vectors for this knowledge base or search with text\",\n\t\t\tembeddingModel.GetModelName(),\n\t\t)\n\t}\n\tprepared, err := imageprep.Prepare(img, imageModel.ImageLimits())\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"query image not embeddable: %w\", err)\n\t}\n\tvectors, err := imageModel.BatchEmbedImages(types.WithEmbedQuery(ctx), []embedding.Image{prepared})\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tif len(vectors) == 0 {\n\t\treturn nil, fmt.Errorf(\"embedding model returned no vector for the query image\")\n\t}\n\tif err := validateQueryEmbeddingDimension(embeddingModel, len(vectors[0])); err != nil {\n\t\tlogger.Errorf(ctx, \"GetQueryImageEmbedding: %v\", err)\n\t\treturn nil, err\n\t}\n\treturn vectors[0], nil\n}\n\n// validateQueryEmbeddingDimension catches provider/model configuration drift\n// before a malformed query reaches the vector store. Without this check, a\n// provider returning a different vector size is reported as the misleading\n// generic 2201 \"bound store unavailable\" error (or, for dimension-partitioned\n// stores, silently produces no matches).\nfunc validateQueryEmbeddingDimension(model embedding.Embedder, actual int) error {\n\tif model == nil || actual == 0 {\n\t\treturn nil\n\t}\n\texpected := model.GetDimensions()\n\tif expected <= 0 || expected == actual {\n\t\treturn nil\n\t}\n\treturn apperrors.NewVectorStoreUnavailableError(\n\t\t\"embedding vector dimension does not match the configured model\",\n\t).WithDetails(map[string]any{\n\t\t\"model\":              model.GetModelName(),\n\t\t\"expected_dimension\": expected,\n\t\t\"actual_dimension\":   actual,\n\t\t\"hint\":               fmt.Sprintf(\"check the embedding model configuration and rebuild the affected index (%d dimensions)\", expected),\n\t})\n}\n\n// ResolveEmbeddingModelKeys resolves embedding model IDs to their actual model\n// identity key (name + endpoint + configured vector dimension). KBs using the\n// same underlying model and vector space across different tenants will share\n// the same key, enabling optimal grouping without reusing a query embedding\n// across incompatible index dimensions.\nfunc (s *knowledgeBaseService) ResolveEmbeddingModelKeys(ctx context.Context, kbs []*types.KnowledgeBase) map[string]string {\n\ttype modelRef struct {\n\t\tModelID  string\n\t\tTenantID uint64\n\t}\n\n\t// Deduplicate model references\n\tuniqueRefs := make(map[modelRef]struct{})\n\tkbRefs := make(map[string]modelRef, len(kbs))\n\tfor _, kb := range kbs {\n\t\tref := modelRef{ModelID: kb.EmbeddingModelID, TenantID: kb.TenantID}\n\t\tuniqueRefs[ref] = struct{}{}\n\t\tkbRefs[kb.ID] = ref\n\t}\n\n\t// Resolve each unique (modelID, tenantID) to a model identity key. The\n\t// configured dimension is part of the key because providers such as OpenAI\n\t// support multiple output widths for one model name and endpoint.\n\tresolvedKeys := make(map[modelRef]string, len(uniqueRefs))\n\tfor ref := range uniqueRefs {\n\t\ttenantCtx := types.WithExecutionTenant(ctx, ref.TenantID)\n\t\tmodel, err := s.modelService.GetModelByID(tenantCtx, ref.ModelID)\n\t\tif err != nil || model == nil {\n\t\t\tlogger.Warnf(ctx, \"ResolveEmbeddingModelKeys: cannot resolve model %s for tenant %d: %v\", ref.ModelID, ref.TenantID, err)\n\t\t\tresolvedKeys[ref] = ref.ModelID\n\t\t\tcontinue\n\t\t}\n\t\tresolvedKeys[ref] = fmt.Sprintf(\"%s|%s|%d\", model.Name, model.Parameters.BaseURL,\n\t\t\tmodel.Parameters.EmbeddingParameters.Dimension)\n\t}\n\n\tresult := make(map[string]string, len(kbs))\n\tfor _, kb := range kbs {\n\t\tresult[kb.ID] = resolvedKeys[kbRefs[kb.ID]]\n\t}\n\treturn result\n}\n\n// HybridSearch performs hybrid search, including vector retrieval and keyword retrieval.\n//\n// id is the \"primary\" knowledge base ID used to resolve the embedding model and\n// determine the KB type (e.g. FAQ). When params.KnowledgeBaseIDs is set, those\n// IDs are used for the actual retrieval scope instead of id alone, allowing a\n// single call to span multiple KBs that share the same embedding model. In that\n// case id should be any one of those KBs (typically the first) so that its\n// embedding model and type configuration are used for the search.\nfunc (s *knowledgeBaseService) HybridSearch(ctx context.Context,\n\tid string,\n\tparams types.SearchParams,\n) ([]*types.SearchResult, error) {\n\t// Normalize once, before anything reads MatchCount. params is a value\n\t// copy, so this stays local to the call.\n\tparams.MatchCount = normalizedMatchCount(params.MatchCount)\n\n\tchunks, err := s.hybridSearchCandidates(ctx, id, params)\n\tif err != nil || len(chunks) == 0 {\n\t\treturn nil, err\n\t}\n\n\trecordImageRecallDecision(ctx, \"fusion.candidate_selection\", \"\",\n\t\tsummarizeImageCandidateCut(chunks, params.MatchCount))\n\n\t// Truncate to the primary-match cap. MatchCount is guaranteed positive by\n\t// the normalization at the top of this function; the slice bound below\n\t// depends on that.\n\tif len(chunks) > params.MatchCount {\n\t\tchunks = chunks[:params.MatchCount]\n\t}\n\n\treturn s.processSearchResults(ctx, chunks, params.SkipContextEnrichment)\n}\n\n// hybridSearchCandidates runs retrieval, fusion and FAQ post-processing for\n// HybridSearch and returns the fused chunks, best first, before the\n// MatchCount cut. params.MatchCount must already be normalized.\nfunc (s *knowledgeBaseService) hybridSearchCandidates(ctx context.Context,\n\tid string,\n\tparams types.SearchParams,\n) ([]*types.IndexWithScore, error) {\n\t// Determine the set of KB IDs to search.\n\tsearchKBIDs := params.KnowledgeBaseIDs\n\tif len(searchKBIDs) == 0 {\n\t\tsearchKBIDs = []string{id}\n\t}\n\n\t// QueryText is user-controlled; sanitize before logging to prevent\n\t// CR/LF/tab log injection. Matches the handler-layer sanitization at\n\t// handler/knowledgebase.go.\n\tlogger.Infof(ctx, \"Hybrid search parameters, knowledge base IDs: %v, query text: %s\",\n\t\tsearchKBIDs, secutils.SanitizeForLog(params.QueryText))\n\n\ttenantInfo, _ := types.TenantInfoFromContext(ctx)\n\n\t// Batch-load every KB in scope. Required for store grouping,\n\t// embedding-model consistency validation, and FAQ type detection.\n\t// GetKnowledgeBaseByIDs is intentionally tenant-agnostic at the\n\t// repository layer so that Organization-shared KBs (owned by a\n\t// different tenant) can be loaded here; authorization for each\n\t// returned row is enforced explicitly below.\n\tkbs, err := s.repo.GetKnowledgeBaseByIDs(ctx, searchKBIDs)\n\tif err != nil {\n\t\tlogger.ErrorWithFields(ctx, err, map[string]interface{}{\n\t\t\t\"knowledge_base_ids\": searchKBIDs,\n\t\t})\n\t\treturn nil, err\n\t}\n\tif len(kbs) == 0 {\n\t\treturn nil, apperrors.NewNotFoundError(\"knowledge base not found\")\n\t}\n\n\t// Authorize every KB for the original caller, using exact upstream\n\t// grants or organization permissions. Execution in a shared tenant\n\t// does not grant access to its other KBs. Without this guard, a\n\t// caller could pass arbitrary KB UUIDs in params.KnowledgeBaseIDs\n\t// and reach foreign tenants' bound vector stores via the per-group\n\t// engine resolution downstream.\n\tif err := s.authorizeKBAccess(ctx, kbs); err != nil {\n\t\treturn nil, err\n\t}\n\n\t// Explicit embedding-model consistency check. Multi-KB searches that\n\t// span different embedding spaces would otherwise silently produce\n\t// meaningless cross-model scores. Same-model wiki/graph KBs are\n\t// tolerated — see validateSameEmbeddingModel for the carve-out.\n\tif err := s.validateSameEmbeddingModel(ctx, kbs); err != nil {\n\t\treturn nil, err\n\t}\n\n\t// Resolve the primary KB — embedding model + FAQ type come from this\n\t// one. Miss → 404 (no kbs[0] fallback; a silent pivot to an arbitrary\n\t// KB would hide caller bugs and reveal foreign KB metadata).\n\tkb := pickPrimary(kbs, id)\n\tif kb == nil {\n\t\treturn nil, apperrors.NewNotFoundError(\"knowledge base not found\")\n\t}\n\n\t// Over-retrieval (existing rule, preserved): 5x per-KB matchCount,\n\t// floored at DefaultRetrievalTopK, capped at maxRetrievalPoolSize across\n\t// the whole search.\n\tmatchCount := max(params.MatchCount*5, types.DefaultRetrievalTopK) * len(searchKBIDs)\n\tif matchCount > maxRetrievalPoolSize {\n\t\tmatchCount = maxRetrievalPoolSize\n\t}\n\n\t// Compute the query embedding once before fan-out and propagate via\n\t// params.QueryEmbedding. Without this, each storeGroup's\n\t// buildRetrievalParams would re-embed the same query text — for N\n\t// stores that means N API calls of identical input.\n\t//\n\t// Skip when params already carries an embedding (e.g. the agent\n\t// pre-computed it) or when the primary KB has no vector indexing\n\t// configured.\n\tembeddingKB := kb\n\tif !hasEmbeddingModel(embeddingKB) {\n\t\tembeddingKB = nil\n\t\tfor _, candidate := range kbs {\n\t\t\tif hasEmbeddingModel(candidate) {\n\t\t\t\tembeddingKB = candidate\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t}\n\tif len(params.QueryEmbedding) == 0 && embeddingKB != nil && !params.DisableVectorMatch {\n\t\temb, embErr := s.GetQueryEmbedding(ctx, embeddingKB.ID, params.QueryText)\n\t\tif embErr != nil {\n\t\t\treturn nil, embErr\n\t\t}\n\t\tparams.QueryEmbedding = emb\n\t}\n\n\t// Group KBs by (storeID, owner tenant), resolve the bound engine for\n\t// each group, and build the per-group base RetrieveParams once.\n\tgroups, err := s.resolveStoreGroups(ctx, kb, kbs, params, matchCount)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tif len(groups) == 0 || allBaseParamsEmpty(groups) {\n\t\t// Wiki-only / graph-only fan-out: every KB is non-retrievable.\n\t\t// Preserve the existing \"return empty rather than error\" contract\n\t\t// so agent tools that combine multiple KB scopes degrade gracefully.\n\t\tlogger.Infof(ctx, \"No retrievable indexing pipelines across %d KBs\", len(kbs))\n\t\treturn nil, nil\n\t}\n\n\t// Image vectors are recalled only for KBs that opted in to them.\n\ts.applyImageRecall(ctx, kbs, groups, params)\n\n\t// Execute retrieval with fan-out + score normalization (multi-store\n\t// only) and a langfuse span around the entire retrieve step.\n\tlogger.Infof(ctx, \"Starting multi-store retrieval, group count: %d\", len(groups))\n\tretrieveCtx, retrieveSpan := langfuse.GetManager().StartSpan(ctx, langfuse.SpanOptions{\n\t\tName: \"retrieve\",\n\t\tInput: map[string]interface{}{\n\t\t\t\"query_text\":             params.QueryText,\n\t\t\t\"kb_ids\":                 searchKBIDs,\n\t\t\t\"knowledge_ids\":          params.KnowledgeIDs,\n\t\t\t\"tag_ids\":                params.TagIDs,\n\t\t\t\"scope_tag_ids\":          params.ScopeTagIDs,\n\t\t\t\"match_count\":            matchCount,\n\t\t\t\"vector_threshold\":       params.VectorThreshold,\n\t\t\t\"keyword_threshold\":      params.KeywordThreshold,\n\t\t\t\"disable_vector_match\":   params.DisableVectorMatch,\n\t\t\t\"disable_keywords_match\": params.DisableKeywordsMatch,\n\t\t\t\"group_count\":            len(groups),\n\t\t},\n\t\tMetadata: map[string]interface{}{\n\t\t\t\"primary_kb_id\":       kb.ID,\n\t\t\t\"primary_kb_type\":     string(kb.Type),\n\t\t\t\"embedding_model_id\":  kb.EmbeddingModelID,\n\t\t\t\"has_query_embedding\": len(params.QueryEmbedding) > 0,\n\t\t},\n\t})\n\tretrieveResults, err := s.retrieveFromStores(retrieveCtx, groups, retriever.EngineAwareNormalizer{})\n\tretrieveSpan.Finish(langfuse.SummarizeRetrieveOutput(retrieveResults), nil, err)\n\tif err != nil {\n\t\tlogger.ErrorWithFields(ctx, err, map[string]interface{}{\n\t\t\t\"knowledge_base_ids\": searchKBIDs,\n\t\t\t\"query_text\":         params.QueryText,\n\t\t})\n\t\treturn nil, err\n\t}\n\n\t// Separate and fuse retrieval results.\n\tvectorLists, keywordLists := classifyRetrievalResults(ctx, retrieveResults)\n\tvectorResults, keywordResults := flattenLists(vectorLists), flattenLists(keywordLists)\n\tif len(vectorResults) == 0 && len(keywordResults) == 0 {\n\t\tlogger.Info(ctx, \"No search results found\")\n\t\treturn nil, nil\n\t}\n\tlogger.Infof(ctx, \"Result count before fusion: vector=%d, keyword=%d\",\n\t\tlen(vectorResults), len(keywordResults))\n\n\tvar retrievalCfg *types.RetrievalConfig\n\tif tenantInfo != nil {\n\t\tretrievalCfg = tenantInfo.RetrievalConfig\n\t}\n\tdeduplicatedChunks := fuseOrDeduplicate(ctx, vectorLists, keywordLists, retrievalCfg)\n\n\tkb.EnsureDefaults()\n\n\t// FAQ-specific post-processing now operates on storeGroups so the\n\t// iterative TopK growth applies uniformly across the fan-out. An\n\t// AppError from inside the iterative fan-out path (e.g. a per-group\n\t// timeout surfaced as ErrVectorStoreUnavailable) must surface to the\n\t// caller rather than be silently converted to a truncated chunk list.\n\treturn s.applyFAQPostProcessing(\n\t\tctx, kb, kbs, deduplicatedChunks, vectorLists, groups, params, matchCount)\n}\n\n// normalizedMatchCount resolves the effective primary-match cap for a search.\n//\n// MatchCount arrives as Go's zero value whenever a caller omits it — JSON\n// cannot tell an absent match_count from an explicit 0 — and three consumers\n// inside HybridSearch read it: the over-retrieval floor, the FAQ\n// iterative-retrieval trigger, and the final truncation. They must agree, so\n// the value is resolved here rather than at each use site. A raw 0 truncates\n// the deduplicated chunk list to [:0] and empties an otherwise successful\n// search; a negative value panics on that same slice bound.\n//\n// The fallback is shared with RetrievalConfig.GetEffectiveEmbeddingTopK:\n// internal callers (chat pipeline, agent tools) feed these results into\n// reranking, which trims to RerankTopK afterwards, so a wide candidate pool is\n// the right failure mode for them.\nfunc normalizedMatchCount(requested int) int {\n\tif requested <= 0 {\n\t\treturn types.DefaultRetrievalTopK\n\t}\n\t// A search never returns more than the pool it draws from, so capping here\n\t// changes no result; it keeps the over-retrieval arithmetic\n\t// (MatchCount*5*len(KBs), the FAQ path's MatchCount*3) from overflowing\n\t// into a negative TopK on absurd input.\n\treturn min(requested, maxRetrievalPoolSize)\n}\n\n// hasEmbeddingModel reports whether kb is vector-indexed with a configured\n// embedding model, i.e. whether it can embed a query for vector retrieval.\nfunc hasEmbeddingModel(kb *types.KnowledgeBase) bool {\n\treturn kb != nil && kb.IsVectorEnabled() && kb.EmbeddingModelID != \"\"\n}\n\n// pickPrimary returns the KB whose ID matches id, or nil if id is not in\n// scope. Callers map a nil result to NotFound; there is intentionally no\n// kbs[0] fallback because it would mask caller bugs and could leak an\n// unintended KB's embedding-model identity into the search path.\n//\n// The primary KB drives the embedding model and FAQ-type decisions for\n// buildRetrievalParams. If the caller selects a wiki-only / graph-only\n// KB as primary, the multi-KB search is implicitly demoted to\n// keyword-only retrieval — vector retrieval is skipped because\n// primary.IsVectorEnabled() is false. Callers that mix vector-enabled\n// and non-vector KBs should pass a vector-enabled KB as id.\nfunc pickPrimary(kbs []*types.KnowledgeBase, id string) *types.KnowledgeBase {\n\tfor _, kb := range kbs {\n\t\tif kb.ID == id {\n\t\t\treturn kb\n\t\t}\n\t}\n\treturn nil\n}\n\n// allBaseParamsEmpty reports whether every store group has an empty\n// BaseParams slice. True only when every KB in scope is wiki-only or\n// graph-only with neither vector nor keyword indexing — HybridSearch then\n// returns nil so callers that combine searchable + non-searchable KBs\n// (agent tools, chat pipeline) degrade gracefully.\nfunc allBaseParamsEmpty(groups []*storeGroup) bool {\n\tfor _, g := range groups {\n\t\tif len(g.BaseParams) > 0 {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\n// totalHits counts the IndexWithScore entries across a slice of retrieve\n// results.\nfunc totalHits(rrs []*types.RetrieveResult) int {\n\tn := 0\n\tfor _, r := range rrs {\n\t\tn += len(r.Results)\n\t}\n\treturn n\n}\n\n// buildRetrievalParams constructs the vector and keyword retrieval parameters\n// for one store group, based on each member KB's type, the engine's\n// capabilities, and the search params.\n//\n// The FAQ-vs-document index decision is a PER-KB property (kb.Type), not a\n// property of the multi-KB search's primary KB. groupKBs therefore drives the\n// routing: KBs in the group are split into a FAQ subset (retrieved from the\n// FAQ vector index) and a document subset (retrieved from the default vector\n// index plus the keyword index). Deciding this from the primary KB alone would\n// route every KB in scope into the primary's index — e.g. a FAQ primary would\n// drag a document-type KB into the FAQ index and skip its keyword recall.\n//\n// primary is used only to resolve the shared query embedding model; every KB\n// in a multi-KB search is guaranteed to share a single embedding model by\n// validateSameEmbeddingModel upstream.\nfunc (s *knowledgeBaseService) buildRetrievalParams(\n\tctx context.Context,\n\tretrieveEngine *retriever.CompositeRetrieveEngine,\n\tprimary *types.KnowledgeBase,\n\tgroupKBs []*types.KnowledgeBase,\n\tparams types.SearchParams,\n\tmatchCount int,\n) ([]types.RetrieveParams, error) {\n\tcurrentTenantID := types.MustTenantIDFromContext(ctx)\n\tvar retrieveParams []types.RetrieveParams\n\n\t// Partition the group's KBs by index routing. A KB that does not have\n\t// vector indexing enabled (e.g. wiki-only or graph-only KBs) has no\n\t// embeddings to retrieve from, and typically has no EmbeddingModelID\n\t// configured either; such KBs are skipped for vector retrieval to avoid\n\t// spurious \"model ID cannot be empty\" errors when an agent's retrieval\n\t// scope happens to include them (e.g. KBSelectionMode=all picking up a\n\t// wiki-only KB).\n\tvar faqVectorKBIDs, docVectorKBIDs, docKeywordKBIDs []string\n\t// Document KBs with question generation off must not spend TopK on\n\t// historical question vectors. FAQ KBs are absent from this list: their\n\t// similar-question rows use the same source-id shape.\n\tvar questionOffKBIDs []string\n\tfor _, kb := range groupKBs {\n\t\tif types.QuestionGenerationDisabled(kb) {\n\t\t\tquestionOffKBIDs = append(questionOffKBIDs, kb.ID)\n\t\t}\n\t}\n\t// The query is embedded with the primary's model, or with the first\n\t// vector KB of the group when the primary has none (a wiki primary\n\t// searched together with document KBs): asking the primary for its empty\n\t// model ID failed the whole search.\n\tembeddingKB := primary\n\tif !hasEmbeddingModel(primary) {\n\t\tembeddingKB = nil\n\t}\n\tfor _, kb := range groupKBs {\n\t\tif hasEmbeddingModel(kb) {\n\t\t\tif embeddingKB == nil {\n\t\t\t\tembeddingKB = kb\n\t\t\t}\n\t\t\tif kb.Type == types.KnowledgeBaseTypeFAQ {\n\t\t\t\tfaqVectorKBIDs = append(faqVectorKBIDs, kb.ID)\n\t\t\t} else {\n\t\t\t\tdocVectorKBIDs = append(docVectorKBIDs, kb.ID)\n\t\t\t}\n\t\t}\n\t\t// FAQ KBs are retrieved exclusively via the FAQ vector index and\n\t\t// have no keyword index; only document-type KBs participate in\n\t\t// keyword retrieval.\n\t\tif kb.IsKeywordEnabled() && kb.Type != types.KnowledgeBaseTypeFAQ {\n\t\t\tdocKeywordKBIDs = append(docKeywordKBIDs, kb.ID)\n\t\t}\n\t}\n\n\t// Add vector retrieval params if supported\n\tif retrieveEngine.SupportRetriever(types.VectorRetrieverType) && !params.DisableVectorMatch &&\n\t\t(len(faqVectorKBIDs) > 0 || len(docVectorKBIDs) > 0) {\n\t\tlogger.Info(ctx, \"Vector retrieval supported, preparing vector retrieval parameters\")\n\n\t\tqueryEmbedding, err := s.resolveQueryEmbedding(ctx, embeddingKB, params, currentTenantID)\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\n\t\tappendVectorParams := func(kbIDs []string, knowledgeType string) {\n\t\t\tretrieveParams = append(retrieveParams, types.RetrieveParams{\n\t\t\t\tQuery:                         params.QueryText,\n\t\t\t\tEmbedding:                     queryEmbedding,\n\t\t\t\tKnowledgeBaseIDs:              kbIDs,\n\t\t\t\tTopK:                          matchCount,\n\t\t\t\tThreshold:                     params.VectorThreshold,\n\t\t\t\tRetrieverType:                 types.VectorRetrieverType,\n\t\t\t\tKnowledgeIDs:                  params.KnowledgeIDs,\n\t\t\t\tTagIDs:                        params.TagIDs,\n\t\t\t\tKnowledgeType:                 knowledgeType,\n\t\t\t\tExcludeGeneratedQuestionKBIDs: generatedQuestionKBIDs(kbIDs, questionOffKBIDs),\n\t\t\t})\n\t\t}\n\n\t\t// Document KBs use the default vector index; FAQ KBs use the FAQ\n\t\t// index. A group containing both types yields one retrieval param\n\t\t// per index so each KB is queried against the index it was written to.\n\t\tif len(docVectorKBIDs) > 0 {\n\t\t\tappendVectorParams(docVectorKBIDs, \"\")\n\t\t}\n\t\tif len(faqVectorKBIDs) > 0 {\n\t\t\tappendVectorParams(faqVectorKBIDs, types.KnowledgeTypeFAQ)\n\t\t}\n\t\tlogger.Info(ctx, \"Vector retrieval parameters setup completed\")\n\t}\n\n\t// Add keyword retrieval params if supported and any document KB has\n\t// keyword indexing enabled.\n\tif retrieveEngine.SupportRetriever(types.KeywordsRetrieverType) && !params.DisableKeywordsMatch &&\n\t\tlen(docKeywordKBIDs) > 0 {\n\t\tlogger.Info(ctx, \"Keyword retrieval supported, preparing keyword retrieval parameters\")\n\t\tretrieveParams = append(retrieveParams, types.RetrieveParams{\n\t\t\tQuery:                         params.QueryText,\n\t\t\tKnowledgeBaseIDs:              docKeywordKBIDs,\n\t\t\tTopK:                          matchCount,\n\t\t\tThreshold:                     params.KeywordThreshold,\n\t\t\tRetrieverType:                 types.KeywordsRetrieverType,\n\t\t\tKnowledgeIDs:                  params.KnowledgeIDs,\n\t\t\tTagIDs:                        params.TagIDs,\n\t\t\tExcludeGeneratedQuestionKBIDs: generatedQuestionKBIDs(docKeywordKBIDs, questionOffKBIDs),\n\t\t})\n\t\tlogger.Info(ctx, \"Keyword retrieval parameters setup completed\")\n\t}\n\n\treturn retrieveParams, nil\n}\n\n// generatedQuestionKBIDs keeps the off-switch ids that this retrieval param\n// actually searches. An empty result leaves the SQL filter off.\nfunc generatedQuestionKBIDs(searched, disabled []string) []string {\n\tif len(searched) == 0 || len(disabled) == 0 {\n\t\treturn nil\n\t}\n\toff := make(map[string]struct{}, len(disabled))\n\tfor _, id := range disabled {\n\t\toff[id] = struct{}{}\n\t}\n\tvar matched []string\n\tfor _, id := range searched {\n\t\tif _, ok := off[id]; ok {\n\t\t\tmatched = append(matched, id)\n\t\t}\n\t}\n\treturn matched\n}\n\n// resolveQueryEmbedding returns the query embedding for a store group. It\n// reuses params.QueryEmbedding when the caller pre-computed it (the common\n// path — HybridSearch embeds once before fan-out), otherwise it embeds the\n// query text using the embedding model of the supplied KB. For cross-tenant\n// shared KBs the source tenant's embedding model is used so the produced\n// vector is compatible with the index it will be searched against.\nfunc (s *knowledgeBaseService) resolveQueryEmbedding(\n\tctx context.Context,\n\tkb *types.KnowledgeBase,\n\tparams types.SearchParams,\n\tcurrentTenantID uint64,\n) ([]float32, error) {\n\tif len(params.QueryEmbedding) > 0 {\n\t\tlogger.Infof(ctx, \"Using pre-computed query embedding, vector length: %d\", len(params.QueryEmbedding))\n\t\treturn params.QueryEmbedding, nil\n\t}\n\n\tlogger.Infof(ctx, \"Getting embedding model, model ID: %s\", kb.EmbeddingModelID)\n\n\tvar embeddingModel embedding.Embedder\n\tvar err error\n\tif kb.TenantID != currentTenantID {\n\t\tlogger.Infof(ctx, \"Cross-tenant knowledge base detected, using source tenant's embedding model. KB tenant: %d, current tenant: %d\", kb.TenantID, currentTenantID)\n\t\tembeddingModel, err = s.modelService.GetEmbeddingModelForTenant(ctx, kb.EmbeddingModelID, kb.TenantID)\n\t} else {\n\t\tembeddingModel, err = s.modelService.GetEmbeddingModel(ctx, kb.EmbeddingModelID)\n\t}\n\tif err != nil {\n\t\tlogger.Errorf(ctx, \"Failed to get embedding model, model ID: %s, error: %v\", kb.EmbeddingModelID, err)\n\t\treturn nil, err\n\t}\n\tlogger.Infof(ctx, \"Embedding model retrieved: %v\", embeddingModel)\n\n\tlogger.Info(ctx, \"Starting to generate query embedding\")\n\tqueryEmbedding, err := embeddingModel.Embed(types.WithEmbedQuery(ctx), params.QueryText)\n\tif err != nil {\n\t\tlogger.Errorf(ctx, \"Failed to embed query text, query text: %s, error: %v\", params.QueryText, err)\n\t\treturn nil, err\n\t}\n\tif err := validateQueryEmbeddingDimension(embeddingModel, len(queryEmbedding)); err != nil {\n\t\tlogger.Errorf(ctx, \"resolveQueryEmbedding: %v\", err)\n\t\treturn nil, err\n\t}\n\tlogger.Infof(ctx, \"Query embedding generated successfully, embedding vector length: %d\", len(queryEmbedding))\n\treturn queryEmbedding, nil\n}\n"
